-- Charta Home · all migrations, in order.
-- Generated by scripts/bundle-migrations.mjs. Do not edit by hand.
-- Paste into the Supabase SQL editor, then run seed.sql.
--
-- Safe to run more than once: a project that already has some of this
-- applied will skip what it has and add only what is missing.

-- ======================================================================
-- Clear what this bundle owns and rebuilds, so it can be run again
-- ======================================================================

drop view if exists v_apartment_performance cascade;
drop view if exists v_apartment_state cascade;
drop view if exists v_building_performance cascade;
drop view if exists v_charge_status cascade;
drop view if exists v_reminder_targets cascade;
drop view if exists v_technician_performance cascade;

do $do$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname = any (array['admin_agency_detail', 'admin_issue_plan_code', 'admin_list_agencies', 'admin_list_subscriptions', 'assign_technician', 'begin_subscription_payment', 'block_delete_occupied_apartment', 'create_agency_for_current_user', 'create_lease', 'current_agency_ids', 'default_pages_for_role', 'enforce_apartment_limit', 'enforce_building_limit', 'ensure_rent_charge', 'has_role', 'is_member', 'is_platform_admin', 'list_agency_members', 'membership_default_pages', 'next_period_start', 'record_payment', 'redeem_plan_code', 'reorder_apartment_photos', 'request_plan', 'resident_by_phone', 'resolve_ticket', 'set_member_pages', 'set_my_display_name', 'settle_subscription_payment', 'take_rate_limit', 'touch_updated_at', 'wa_followup_window', 'wa_route_inbound', 'wa_set_state', 'write_audit'])
  loop
    execute format('drop function if exists %s cascade', f.sig);
  end loop;
end $do$;

do $do$
declare p record;
begin
  for p in
    select tablename, policyname from pg_policies
    where schemaname = 'public'
      and tablename = any (array['agencies', 'apartment_photos', 'apartments', 'audit_log', 'building_owners', 'buildings', 'events', 'expenses', 'leases', 'memberships', 'owners', 'payment_allocations', 'payments', 'plan_codes', 'plan_limits', 'plan_prices', 'plan_requests', 'plans', 'platform_admins', 'rate_limits', 'reminder_events', 'reminder_rules', 'rent_charges', 'residents', 'subscription_payments', 'subscriptions', 'technicians', 'ticket_messages', 'tickets', 'wa_conversations'])
  loop
    execute format('drop policy %I on public.%I', p.policyname, p.tablename);
  end loop;
end $do$;

