-- 20260808120100_portfolio.sql
-- ======================================================================

-- Charta Home · portfolio, people and contracts

-- ---------------------------------------------------------------- buildings

create table if not exists buildings (
  id                uuid primary key default gen_random_uuid(),
  agency_id         uuid not null references agencies (id) on delete cascade,
  name              text not null check (length(btrim(name)) > 0),
  address           text not null default '',
  city              text not null default '',
  -- Net yield needs a valuation. Without this the percentage is meaningless.
  acquisition_value bigint check (acquisition_value >= 0),
  market_value      bigint check (market_value >= 0),
  photo_path        text,
  interior_path     text,
  amenities         text[] not null default '{}',
  notes             text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index if not exists buildings_agency_idx on buildings (agency_id);

drop trigger if exists buildings_touch on buildings;
create trigger buildings_touch before update on buildings
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------- apartments

create table if not exists apartments (
  id          uuid primary key default gen_random_uuid(),
  agency_id   uuid not null references agencies (id) on delete cascade,
  building_id uuid not null references buildings (id) on delete cascade,
  label       text not null check (length(btrim(label)) > 0),
  floor       text,
  rooms       smallint not null default 1 check (rooms >= 0),
  bathrooms   smallint not null default 1 check (bathrooms >= 0),
  sqm         numeric(8, 2) check (sqm > 0),
  base_rent   bigint not null default 0 check (base_rent >= 0),
  photo_path  text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (building_id, label)
);

create index if not exists apartments_building_idx on apartments (building_id);
create index if not exists apartments_agency_idx on apartments (agency_id);

drop trigger if exists apartments_touch on apartments;
create trigger apartments_touch before update on apartments
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------- residents
-- "resident" rather than "tenant" so the word tenant always means an agency.

create table if not exists residents (
  id            uuid primary key default gen_random_uuid(),
  agency_id     uuid not null references agencies (id) on delete cascade,
  full_name     text not null check (length(btrim(full_name)) > 0),
  phone_e164    text check (phone_e164 ~ '^\+[1-9][0-9]{6,14}$'),
  email         citext,
  id_document_path text,
  notes         text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index if not exists residents_agency_idx on residents (agency_id);
create index if not exists residents_phone_idx on residents (phone_e164);

drop trigger if exists residents_touch on residents;
create trigger residents_touch before update on residents
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------- owners

create table if not exists owners (
  id         uuid primary key default gen_random_uuid(),
  agency_id  uuid not null references agencies (id) on delete cascade,
  full_name  text not null,
  email      citext,
  phone_e164 text,
  created_at timestamptz not null default now()
);

create table if not exists building_owners (
  building_id uuid not null references buildings (id) on delete cascade,
  owner_id    uuid not null references owners (id) on delete cascade,
  agency_id   uuid not null references agencies (id) on delete cascade,
  share       numeric(5, 2) not null default 100 check (share > 0 and share <= 100),
  primary key (building_id, owner_id)
);

create index if not exists owners_agency_idx on owners (agency_id);
create index if not exists building_owners_agency_idx on building_owners (agency_id);

-- ---------------------------------------------------------------- leases

create table if not exists leases (
  id           uuid primary key default gen_random_uuid(),
  agency_id    uuid not null references agencies (id) on delete cascade,
  apartment_id uuid not null references apartments (id) on delete cascade,
  resident_id  uuid not null references residents (id) on delete restrict,
  cycle        lease_cycle not null default 'monthly',
  rent_amount  bigint not null check (rent_amount >= 0),
  deposit      bigint not null default 0 check (deposit >= 0),
  due_day      smallint not null default 1 check (due_day between 1 and 28),
  starts_on    date not null,
  ends_on      date,
  status       lease_status not null default 'active',
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  constraint leases_dates_ordered check (ends_on is null or ends_on >= starts_on)
);

create index if not exists leases_apartment_idx on leases (apartment_id);
create index if not exists leases_resident_idx on leases (resident_id);
create index if not exists leases_agency_idx on leases (agency_id);

-- One active lease per apartment at a time.
create unique index if not exists leases_one_active_per_apartment
  on leases (apartment_id)
  where status = 'active';

drop trigger if exists leases_touch on leases;
create trigger leases_touch before update on leases
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------- policies

alter table buildings       enable row level security;
alter table apartments      enable row level security;
alter table residents       enable row level security;
alter table owners          enable row level security;
alter table building_owners enable row level security;
alter table leases          enable row level security;

-- Members read everything in their agency; owners, managers and accountants write.
do $$
declare
  tbl text;
begin
  foreach tbl in array array['buildings', 'apartments', 'residents', 'owners', 'building_owners', 'leases']
  loop
    execute format(
      'create policy %1$s_select on %1$s for select using (agency_id in (select public.current_agency_ids()))',
      tbl
    );
    execute format(
      'create policy %1$s_insert on %1$s for insert with check (public.has_role(agency_id, array[''owner'', ''manager'', ''accountant'']::member_role[]))',
      tbl
    );
    execute format(
      'create policy %1$s_update on %1$s for update using (public.has_role(agency_id, array[''owner'', ''manager'', ''accountant'']::member_role[])) with check (public.has_role(agency_id, array[''owner'', ''manager'', ''accountant'']::member_role[]))',
      tbl
    );
    execute format(
      'create policy %1$s_delete on %1$s for delete using (public.has_role(agency_id, array[''owner'', ''manager'']::member_role[]))',
      tbl
    );
  end loop;
end $$;

-- ======================================================================
-- 20260808120200_money.sql
-- ======================================================================

-- Charta Home · money
-- All amounts are integers in the smallest unit of the agency currency.
-- The Guinean franc has no subunit, so a GNF amount is whole francs.
-- rent_charges is the ledger. Payments allocate against charges, and status is
-- derived rather than stored so it can never drift.

create table if not exists rent_charges (
  id            uuid primary key default gen_random_uuid(),
  agency_id     uuid not null references agencies (id) on delete cascade,
  lease_id      uuid not null references leases (id) on delete cascade,
  period_start  date not null,
  period_end    date not null,
  amount        bigint not null check (amount >= 0),
  due_on        date not null,
  status        charge_status not null default 'open',
  created_at    timestamptz not null default now(),
  constraint rent_charges_period_ordered check (period_end >= period_start),
  unique (lease_id, period_start)
);

create index if not exists rent_charges_lease_idx on rent_charges (lease_id);
create index if not exists rent_charges_agency_due_idx on rent_charges (agency_id, due_on);
create index if not exists rent_charges_open_idx on rent_charges (agency_id, due_on) where status = 'open';

create table if not exists payments (
  id           uuid primary key default gen_random_uuid(),
  agency_id    uuid not null references agencies (id) on delete cascade,
  lease_id     uuid not null references leases (id) on delete cascade,
  amount       bigint not null check (amount > 0),
  paid_on      date not null default current_date,
  method       payment_method not null default 'cash',
  reference    text,
  recorded_by  uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now()
);

create index if not exists payments_lease_idx on payments (lease_id);
create index if not exists payments_agency_paid_idx on payments (agency_id, paid_on);

create table if not exists payment_allocations (
  payment_id     uuid not null references payments (id) on delete cascade,
  rent_charge_id uuid not null references rent_charges (id) on delete cascade,
  agency_id      uuid not null references agencies (id) on delete cascade,
  amount         bigint not null check (amount > 0),
  primary key (payment_id, rent_charge_id)
);

create index if not exists payment_allocations_charge_idx on payment_allocations (rent_charge_id);

create table if not exists expenses (
  id           uuid primary key default gen_random_uuid(),
  agency_id    uuid not null references agencies (id) on delete cascade,
  building_id  uuid not null references buildings (id) on delete cascade,
  apartment_id uuid references apartments (id) on delete set null,
  ticket_id    uuid,
  category     text not null default 'maintenance',
  amount       bigint not null check (amount >= 0),
  incurred_on  date not null default current_date,
  description  text,
  receipt_path text,
  created_at   timestamptz not null default now()
);

create index if not exists expenses_building_idx on expenses (building_id);
create index if not exists expenses_agency_date_idx on expenses (agency_id, incurred_on);

-- ------------------------------------------------------------ derived views

-- How much of each charge has been settled, and whether it is late today.
create or replace view v_charge_status
with (security_invoker = true)
as
select
  c.id            as rent_charge_id,
  c.agency_id,
  c.lease_id,
  c.period_start,
  c.period_end,
  c.due_on,
  c.amount,
  coalesce(sum(a.amount), 0)::bigint                 as paid_amount,
  (c.amount - coalesce(sum(a.amount), 0))::bigint    as balance,
  case
    when c.status = 'void' then 'void'
    when coalesce(sum(a.amount), 0) >= c.amount then 'paid'
    when c.due_on < current_date then 'overdue'
    else 'pending'
  end                                                as state
from rent_charges c
left join payment_allocations a on a.rent_charge_id = c.id
group by c.id;

-- One row per apartment with its live lease and current rent state.
create or replace view v_apartment_state
with (security_invoker = true)
as
select
  ap.id            as apartment_id,
  ap.agency_id,
  ap.building_id,
  ap.label,
  ap.rooms,
  ap.bathrooms,
  ap.sqm,
  ap.base_rent,
  l.id             as lease_id,
  l.cycle,
  l.rent_amount,
  r.id             as resident_id,
  r.full_name      as resident_name,
  r.phone_e164     as resident_phone,
  l.starts_on      as lease_started_on,
  (l.id is not null) as is_occupied,
  case
    when l.id is null then null
    else (
      select cs.state
      from v_charge_status cs
      where cs.lease_id = l.id
      order by cs.period_start desc
      limit 1
    )
  end as rent_state
from apartments ap
left join leases l
  on l.apartment_id = ap.id and l.status = 'active'
left join residents r
  on r.id = l.resident_id;

-- Per building performance, the numbers behind the ROI cards.
create or replace view v_building_performance
with (security_invoker = true)
as
select
  b.id                            as building_id,
  b.agency_id,
  b.name,
  count(ap.id)                    as apartment_count,
  count(ap.id) filter (where st.is_occupied) as occupied_count,
  coalesce(sum(ap.sqm), 0)        as total_sqm,
  coalesce(
    (
      select sum(p.amount)
      from payments p
      join leases l2 on l2.id = p.lease_id
      join apartments ap2 on ap2.id = l2.apartment_id
      where ap2.building_id = b.id
        and p.paid_on >= date_trunc('year', current_date)
    ),
    0
  )::bigint                        as income_ytd,
  coalesce(
    (
      select sum(e.amount)
      from expenses e
      where e.building_id = b.id
        and e.incurred_on >= date_trunc('year', current_date)
    ),
    0
  )::bigint                        as expenses_ytd,
  case
    when coalesce(b.market_value, b.acquisition_value, 0) > 0 then
      round(
        (
          coalesce(
            (
              select sum(p.amount) from payments p
              join leases l3 on l3.id = p.lease_id
              join apartments ap3 on ap3.id = l3.apartment_id
              where ap3.building_id = b.id
                and p.paid_on >= date_trunc('year', current_date)
            ), 0
          )
          - coalesce(
            (
              select sum(e.amount) from expenses e
              where e.building_id = b.id
                and e.incurred_on >= date_trunc('year', current_date)
            ), 0
          )
        )::numeric * 100 / coalesce(b.market_value, b.acquisition_value),
        2
      )
    else null
  end                              as net_yield_pct
from buildings b
left join apartments ap on ap.building_id = b.id
left join v_apartment_state st on st.apartment_id = ap.id
group by b.id;

-- ---------------------------------------------------------------- policies

alter table rent_charges         enable row level security;
alter table payments             enable row level security;
alter table payment_allocations  enable row level security;
alter table expenses             enable row level security;

do $$
declare
  tbl text;
begin
  foreach tbl in array array['rent_charges', 'payments', 'payment_allocations', 'expenses']
  loop
    execute format(
      'create policy %1$s_select on %1$s for select using (agency_id in (select public.current_agency_ids()))',
      tbl
    );
    execute format(
      'create policy %1$s_insert on %1$s for insert with check (public.has_role(agency_id, array[''owner'', ''manager'', ''accountant'']::member_role[]))',
      tbl
    );
    execute format(
      'create policy %1$s_update on %1$s for update using (public.has_role(agency_id, array[''owner'', ''manager'', ''accountant'']::member_role[])) with check (public.has_role(agency_id, array[''owner'', ''manager'', ''accountant'']::member_role[]))',
      tbl
    );
    execute format(
      'create policy %1$s_delete on %1$s for delete using (public.has_role(agency_id, array[''owner'']::member_role[]))',
      tbl
    );
  end loop;
end $$;

-- ======================================================================
-- 20260808120300_operations.sql
-- ======================================================================

-- Charta Home · maintenance, schedule, billing, audit

create table if not exists technicians (
  id          uuid primary key default gen_random_uuid(),
  agency_id   uuid not null references agencies (id) on delete cascade,
  full_name   text not null,
  trade       text,
  phone_e164  text,
  is_external boolean not null default true,
  created_at  timestamptz not null default now()
);

create index if not exists technicians_agency_idx on technicians (agency_id);

create table if not exists tickets (
  id            uuid primary key default gen_random_uuid(),
  agency_id     uuid not null references agencies (id) on delete cascade,
  building_id   uuid not null references buildings (id) on delete cascade,
  apartment_id  uuid references apartments (id) on delete set null,
  resident_id   uuid references residents (id) on delete set null,
  technician_id uuid references technicians (id) on delete set null,
  title         text not null check (length(btrim(title)) > 0),
  description   text,
  status        ticket_status not null default 'new',
  priority      ticket_priority not null default 'normal',
  reported_via  report_channel not null default 'whatsapp',
  cost          bigint check (cost >= 0),
  opened_at     timestamptz not null default now(),
  resolved_at   timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint tickets_resolved_has_time check (
    (status = 'resolved' and resolved_at is not null)
    or (status <> 'resolved')
  )
);

create index if not exists tickets_building_idx on tickets (building_id);
create index if not exists tickets_agency_opened_idx on tickets (agency_id, opened_at desc);
create index if not exists tickets_open_idx on tickets (agency_id) where status <> 'resolved';

drop trigger if exists tickets_touch on tickets;
create trigger tickets_touch before update on tickets
  for each row execute function public.touch_updated_at();

alter table expenses drop constraint if exists expenses_ticket_fk;
alter table expenses
  add constraint expenses_ticket_fk
  foreign key (ticket_id) references tickets (id) on delete set null;

create table if not exists ticket_messages (
  id                  uuid primary key default gen_random_uuid(),
  agency_id           uuid not null references agencies (id) on delete cascade,
  ticket_id           uuid not null references tickets (id) on delete cascade,
  direction           text not null check (direction in ('inbound', 'outbound')),
  body                text,
  media_path          text,
  provider_message_id text,
  created_at          timestamptz not null default now()
);

create unique index if not exists ticket_messages_provider_uniq
  on ticket_messages (provider_message_id)
  where provider_message_id is not null;

create index if not exists ticket_messages_ticket_idx on ticket_messages (ticket_id, created_at);

-- ---------------------------------------------------------------- schedule

create table if not exists events (
  id           uuid primary key default gen_random_uuid(),
  agency_id    uuid not null references agencies (id) on delete cascade,
  building_id  uuid not null references buildings (id) on delete cascade,
  apartment_id uuid references apartments (id) on delete set null,
  kind         event_kind not null default 'viewing',
  title        text not null,
  detail       text,
  starts_at    timestamptz not null,
  assignee     text,
  created_at   timestamptz not null default now()
);

