-- Charta Home · apartment photo galleries and technician performance

-- ------------------------------------------------------- apartment photos
-- An apartment has an ordered gallery rather than a single photo column, so
-- images can be added, reordered and removed independently.

create table if not exists apartment_photos (
  id           uuid primary key default gen_random_uuid(),
  agency_id    uuid not null references agencies (id) on delete cascade,
  apartment_id uuid not null references apartments (id) on delete cascade,
  storage_path text not null,
  caption      text,
  position     smallint not null default 0,
  created_at   timestamptz not null default now()
);

create index if not exists apartment_photos_apartment_idx on apartment_photos (apartment_id, position);
create index if not exists apartment_photos_agency_idx on apartment_photos (agency_id);

alter table apartment_photos enable row level security;

drop policy if exists apartment_photos_select on apartment_photos;
create policy apartment_photos_select on apartment_photos for select
  using (agency_id in (select public.current_agency_ids()));

drop policy if exists apartment_photos_write on apartment_photos;
create policy apartment_photos_write on apartment_photos for all
  using (public.has_role(agency_id, array['owner', 'manager', 'accountant']::public.member_role[]))
  with check (public.has_role(agency_id, array['owner', 'manager', 'accountant']::public.member_role[]));

-- Keep positions contiguous when a photo is removed.
create or replace function public.reorder_apartment_photos()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.apartment_photos p
  set position = ordered.new_position
  from (
    select id, (row_number() over (order by position, created_at) - 1)::smallint as new_position
    from public.apartment_photos
    where apartment_id = old.apartment_id
  ) ordered
  where p.id = ordered.id and p.position is distinct from ordered.new_position;

  return null;
end;
$$;

drop trigger if exists apartment_photos_reorder on apartment_photos;
create trigger apartment_photos_reorder after delete on apartment_photos
  for each row execute function public.reorder_apartment_photos();

-- --------------------------------------------------- technician performance
-- Powers the technicians tab: how many jobs, how much paid, how fast.

create or replace view v_technician_performance
with (security_invoker = true)
as
select
  tech.id                as technician_id,
  tech.agency_id,
  tech.full_name,
  tech.trade,
  tech.phone_e164,
  tech.is_external,
  count(t.id)                                              as jobs_total,
  count(t.id) filter (where t.status = 'resolved')          as jobs_resolved,
  count(t.id) filter (where t.status <> 'resolved')         as jobs_open,
  coalesce(sum(t.cost) filter (where t.status = 'resolved'), 0)::bigint as total_paid,
  round(
    avg(
      extract(epoch from (t.resolved_at - t.opened_at)) / 86400
    ) filter (where t.status = 'resolved')::numeric,
    1
  )                       as avg_days_to_resolve,
  max(t.resolved_at)      as last_job_at
from technicians tech
left join tickets t on t.technician_id = tech.id
group by tech.id;

-- ------------------------------------------------------------ reassignment
-- Reassigning is not a plain update: it should record who took over and reset
-- the ticket to assigned so the new technician sees it as fresh work.

create or replace function public.assign_technician(
  target_ticket uuid,
  target_technician uuid,
  estimated_cost bigint default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  tk record;
  tech record;
begin
  select * into tk from public.tickets where id = target_ticket;
  if not found then
    raise exception 'ticket % not found', target_ticket;
  end if;
  if not public.is_member(tk.agency_id) then
    raise exception 'not a member of this agency';
  end if;

  select * into tech from public.technicians where id = target_technician;
  if not found or tech.agency_id <> tk.agency_id then
    raise exception 'technician % is not in this agency', target_technician;
  end if;

  update public.tickets
  set technician_id = target_technician,
      status = case when status = 'resolved' then status else 'assigned' end,
      cost = coalesce(estimated_cost, cost)
  where id = target_ticket;

  insert into public.ticket_messages (agency_id, ticket_id, direction, body)
  values (
    tk.agency_id,
    target_ticket,
    'outbound',
    case
      when tk.technician_id is null then 'Assigné à ' || tech.full_name
      else 'Réassigné à ' || tech.full_name
    end
  );
end;
$$;

grant execute on function public.assign_technician to authenticated;

-- ======================================================================
-- 20260808120700_settings.sql
-- ======================================================================

-- Charta Home · settings page support
--
-- The settings screen needs the team roster with each member's email, and
-- auth.users is not reachable through PostgREST. list_agency_members bridges
-- it the same way the rest of the schema bridges auth: a security definer
-- function that checks membership itself rather than trusting the caller.

create or replace function public.list_agency_members(target_agency uuid)
returns table (
  user_id    uuid,
  full_name  text,
  role       public.member_role,
  email      text,
  created_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_member(target_agency) then
    raise exception 'not a member of this agency';
  end if;

  return query
    select m.user_id, m.full_name, m.role, u.email::text, m.created_at
    from public.memberships m
    join auth.users u on u.id = m.user_id
    where m.agency_id = target_agency
    order by m.created_at;
end;
$$;

grant execute on function public.list_agency_members to authenticated;

comment on function public.list_agency_members is
  'The settings team roster, email included. Raises unless the caller belongs to the agency.';

-- ======================================================================
-- 20260808120800_lease_end_date.sql
-- ======================================================================

-- Charta Home · lease end date
--
-- `leases.ends_on` has existed since the portfolio migration, with a check
-- that it cannot precede the start, but nothing could set it: create_lease
-- took no such argument and v_apartment_state never selected it. An agency
-- signing a fixed term lease had nowhere to record when the tenant leaves.

-- The view gains the column. Replaced rather than dropped, because
-- v_building_performance is built on top of it and a drop would take that
-- with it. create or replace can only append, so lease_ends_on goes last
-- even though it reads better beside lease_started_on.
create or replace view v_apartment_state
with (security_invoker = true)
as
select
  ap.id            as apartment_id,
  ap.agency_id,
  ap.building_id,
  ap.label,
  ap.rooms,
  ap.bathrooms,
  ap.sqm,
  ap.base_rent,
  l.id             as lease_id,
  l.cycle,
  l.rent_amount,
  r.id             as resident_id,
  r.full_name      as resident_name,
  r.phone_e164     as resident_phone,
  l.starts_on      as lease_started_on,
  (l.id is not null) as is_occupied,
  case
    when l.id is null then null
    else (
      select cs.state
      from v_charge_status cs
      where cs.lease_id = l.id
      order by cs.period_start desc
      limit 1
    )
  end as rent_state,
  l.ends_on        as lease_ends_on
from apartments ap
left join leases l
  on l.apartment_id = ap.id and l.status = 'active'
left join residents r
  on r.id = l.resident_id;

-- Dropped rather than replaced: adding a defaulted parameter would leave the
-- old signature in place and make every existing call ambiguous.
drop function if exists public.create_lease(uuid, text, text, bigint, lease_cycle, date, bigint);

create function public.create_lease(
  target_apartment uuid,
  resident_name text,
  resident_phone text,
  rent bigint,
  cycle_in lease_cycle default 'monthly',
  starts_on_in date default current_date,
  deposit_in bigint default 0,
  ends_on_in date default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  ap record;
  resident uuid;
  new_lease uuid;
begin
  select * into ap from public.apartments where id = target_apartment;
  if not found then
    raise exception 'apartment % not found', target_apartment;
  end if;
  if not public.has_role(ap.agency_id, array['owner', 'manager']::public.member_role[]) then
    raise exception 'not allowed to create leases for this agency';
  end if;

  -- A move out date before the move in date is a typo, not a lease.
  if ends_on_in is not null and ends_on_in < starts_on_in then
    raise exception 'lease cannot end before it starts';
  end if;

  select id into resident
  from public.residents
  where agency_id = ap.agency_id and phone_e164 = resident_phone
  limit 1;

  if resident is null then
    insert into public.residents (agency_id, full_name, phone_e164)
    values (ap.agency_id, resident_name, resident_phone)
    returning id into resident;
  end if;

  insert into public.leases (
    agency_id, apartment_id, resident_id, cycle, rent_amount, deposit,
    starts_on, ends_on, status
  )
  values (
    ap.agency_id, ap.id, resident, cycle_in, rent, deposit_in,
    starts_on_in, ends_on_in, 'active'
  )
  returning id into new_lease;

  perform public.ensure_rent_charge(new_lease, starts_on_in);

  return new_lease;
end;
$$;

grant execute on function public.create_lease to authenticated;

-- ======================================================================
-- 20260808120900_reminder_messages.sql
-- ======================================================================

-- Charta Home · editable reminder messages
--
-- Until now a reminder rule knew when to fire and on what channel, but not
-- what to say. The agency needs to write that themselves: the tone an agency
-- in Conakry uses with its tenants is theirs, not ours.
--
-- message_body holds the text with placeholders the dispatcher fills in:
--   {tenant} {amount} {period} {days} {agency} {apartment}
--
-- template_name stays alongside it. Meta refuses free text outside the 24 hour
-- customer service window, so a proactive reminder needs an approved template;
-- the body is then what the agency submitted for approval and what fills the
-- template's variables.

alter table reminder_rules
  add column if not exists message_body text;

-- Sensible French defaults so an agency is never left with a blank message.
-- Matched on the sign of the offset rather than an exact value, since the
-- courtesy lead time is the agency's to choose.
update reminder_rules
set message_body = case
  when offset_days < 0 then
    'Bonjour {tenant}, votre loyer de {amount} pour {apartment} est attendu dans {days} jours, le {period}. Merci de votre confiance. {agency}'
  when offset_days = 0 then
    'Bonjour {tenant}, votre loyer de {amount} pour {apartment} est dû aujourd''hui. Merci de votre confiance. {agency}'
  when escalation_step >= 2 then
    'Bonjour {tenant}, le loyer de {amount} pour {apartment} reste impayé depuis {days} jours. Merci de nous contacter rapidement. {agency}'
  else
    'Bonjour {tenant}, nous n''avons pas encore reçu le loyer de {amount} pour {apartment}, dû le {period}. Merci de régulariser. {agency}'
end
where message_body is null;

comment on column reminder_rules.message_body is
  'What the reminder says. Placeholders: {tenant} {amount} {period} {days} {agency} {apartment}.';

-- The dispatcher needs the resident's name and number, the unit, and the
-- agency's WhatsApp identity, all of which sit several joins from a charge.
-- One view so the cron reads a queue rather than assembling it row by row.
create or replace view v_reminder_targets
with (security_invoker = true)
as
select
  rc.id            as rent_charge_id,
  rc.agency_id,
  rc.due_on,
  rc.amount,
  ag.name          as agency_name,
  ag.whatsapp_number as agency_whatsapp,
  ag.currency,
  r.full_name      as resident_name,
  r.phone_e164     as resident_phone,
  ap.label         as apartment_label
from rent_charges rc
join leases l    on l.id = rc.lease_id
join residents r on r.id = l.resident_id
join apartments ap on ap.id = l.apartment_id
join agencies ag on ag.id = rc.agency_id;

-- ======================================================================
-- 20260808121000_integrity_and_limits.sql
-- ======================================================================

-- Charta Home · guards that belong in the database
--
-- Two of these existed only in application code, which means they held for the
-- dashboard and not for anyone calling PostgREST directly with their own token.
-- A rule that protects payment history should not depend on which client asked.

-- ------------------------------------------- deleting an occupied apartment
-- apartments cascades to leases, which cascades to rent_charges and payments.
-- Deleting a unit somebody still lives in therefore erases the money it has
-- collected. The server action refused this already; now the database does.

create or replace function public.block_delete_occupied_apartment()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (
    select 1 from public.leases
    where apartment_id = old.id and status = 'active'
  ) then
    raise exception 'apartment % still has an active lease', old.id
      using errcode = 'restrict_violation',
            hint = 'End the lease before deleting the unit.';
  end if;
  return old;
end;
$$;

drop trigger if exists apartments_block_occupied_delete on apartments;
drop trigger if exists apartments_block_occupied_delete on apartments;
create trigger apartments_block_occupied_delete
  before delete on apartments
  for each row execute function public.block_delete_occupied_apartment();

-- ------------------------------------------------------------ rate limiting
-- The WhatsApp webhook verifies Meta's signature but nothing bounded how often
-- it could be called. Serverless instances share no memory, so the counter
-- lives in Postgres, which every instance already talks to.

create table if not exists rate_limits (
  bucket       text primary key,
  window_start timestamptz not null default now(),
  hits         integer not null default 0
);

alter table rate_limits enable row level security;
-- No policies: only the service role, which bypasses RLS, ever touches this.

comment on table rate_limits is
  'Fixed window counters for unauthenticated endpoints. Service role only.';

/**
 * Records one hit and reports whether it is allowed.
 *
 * A fixed window rather than a sliding one: it is one row and one statement,
 * and for shedding a flood the difference does not matter. The upsert makes
 * the read and the increment a single atomic step, so two instances arriving
 * together cannot both see the count below the limit.
 */
create or replace function public.take_rate_limit(
  bucket_key text,
  max_hits integer,
  window_seconds integer
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_hits integer;
begin
  insert into public.rate_limits (bucket, window_start, hits)
  values (bucket_key, now(), 1)
  on conflict (bucket) do update
    set hits = case
          when public.rate_limits.window_start < now() - make_interval(secs => window_seconds)
            then 1
          else public.rate_limits.hits + 1
        end,
        window_start = case
          when public.rate_limits.window_start < now() - make_interval(secs => window_seconds)
            then now()
          else public.rate_limits.window_start
        end
  returning hits into current_hits;

  return current_hits <= max_hits;
end;
$$;

revoke all on function public.take_rate_limit from public;

-- ======================================================================
-- 20260808121100_quarterly_lease_cycle.sql
-- ======================================================================

-- Charta Home · quarterly leases
--
-- The cycle only ever offered monthly or yearly. Agencies in Conakry commonly
-- let on a three month term, which had to be recorded as monthly and then
-- corrected by hand every quarter. This adds the term the market actually uses.

-- Postgres allows a new enum value inside a transaction but forbids using it as
-- a literal in that same transaction. Every comparison below therefore goes
-- through text, which is settled at run time and so is safe to write here.
alter type lease_cycle add value if not exists 'quarterly';

-- --------------------------------------------------------- charge generation
-- The billing period follows the cycle: one month, one quarter, or one year.
-- Anything unrecognised falls back to monthly, which is the shortest period and
-- so the one that under bills rather than over bills if a cycle is ever added
-- without this function being taught about it.
create or replace function public.ensure_rent_charge(
  target_lease uuid,
  period date
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  l record;
  start_on date;
  end_on date;
  charge_id uuid;
begin
  select * into l from public.leases where id = target_lease;
  if not found then
    raise exception 'lease % not found', target_lease;
  end if;
  if not public.is_member(l.agency_id) then
    raise exception 'not a member of this agency';
  end if;

  if l.cycle::text = 'yearly' then
    start_on := date_trunc('year', period)::date;
    end_on := (date_trunc('year', period) + interval '1 year - 1 day')::date;
  elsif l.cycle::text = 'quarterly' then
    start_on := date_trunc('quarter', period)::date;
    end_on := (date_trunc('quarter', period) + interval '3 months - 1 day')::date;
  else
    start_on := date_trunc('month', period)::date;
    end_on := (date_trunc('month', period) + interval '1 month - 1 day')::date;
  end if;

  insert into public.rent_charges (agency_id, lease_id, period_start, period_end, amount, due_on)
  values (
    l.agency_id,
    l.id,
    start_on,
    end_on,
    l.rent_amount,
    (start_on + (l.due_day - 1) * interval '1 day')::date
  )
  on conflict (lease_id, period_start) do nothing
  returning id into charge_id;

  if charge_id is null then
    select id into charge_id
    from public.rent_charges
    where lease_id = l.id and period_start = start_on;
  end if;

  return charge_id;
end;
$$;

grant execute on function public.ensure_rent_charge to authenticated;

-- ======================================================================
-- 20260808121200_daily_lease_cycle.sql
-- ======================================================================

-- Charta Home · daily leases
--
-- Short stay letting is ordinary business for an agency in Conakry: a
-- furnished flat taken for a week, a room let by the night. Recording that as
-- a monthly lease meant one charge covering a stay that had already ended.
--
-- A daily charge covers exactly the day it is raised. The due day, which for a
-- monthly lease says which day of the month rent falls on, has nothing to
-- describe here, so a daily charge is due on the day itself.

alter type lease_cycle add value if not exists 'daily';

-- --------------------------------------------------------- charge generation
-- One day, one month, one quarter, or one year. Anything unrecognised still
-- falls back to monthly, which under bills rather than over bills if a cycle
-- is ever added without this function being taught about it.
create or replace function public.ensure_rent_charge(
  target_lease uuid,
  period date
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  l record;
  start_on date;
  end_on date;
  due date;
  charge_id uuid;
begin
  select * into l from public.leases where id = target_lease;
  if not found then
    raise exception 'lease % not found', target_lease;
  end if;
  if not public.is_member(l.agency_id) then
    raise exception 'not a member of this agency';
  end if;

  if l.cycle::text = 'yearly' then
    start_on := date_trunc('year', period)::date;
    end_on := (date_trunc('year', period) + interval '1 year - 1 day')::date;
  elsif l.cycle::text = 'quarterly' then
    start_on := date_trunc('quarter', period)::date;
    end_on := (date_trunc('quarter', period) + interval '3 months - 1 day')::date;
  elsif l.cycle::text = 'daily' then
    start_on := period;
    end_on := period;
  else
    start_on := date_trunc('month', period)::date;
    end_on := (date_trunc('month', period) + interval '1 month - 1 day')::date;
  end if;

  -- A day long charge is due that day. Offsetting by due_day would push it
  -- past the end of the period it bills for.
  if l.cycle::text = 'daily' then
    due := start_on;
  else
    due := (start_on + (l.due_day - 1) * interval '1 day')::date;
  end if;

  insert into public.rent_charges (agency_id, lease_id, period_start, period_end, amount, due_on)
  values (l.agency_id, l.id, start_on, end_on, l.rent_amount, due)
  on conflict (lease_id, period_start) do nothing
  returning id into charge_id;

  if charge_id is null then
    select id into charge_id
    from public.rent_charges
    where lease_id = l.id and period_start = start_on;
  end if;

  return charge_id;
end;
$$;

grant execute on function public.ensure_rent_charge to authenticated;

-- ======================================================================
-- 20260808121300_own_name_and_agency_owner.sql
-- ======================================================================

-- Charta Home · your own name, and whose agency it is
--
-- Two rules that were wrong in opposite directions. Nobody but the owner could
-- change a name, including their own, and anyone the owner made a manager
-- could rename the agency and change the number tenants reply to.

-- ------------------------------------------------------ setting your own name
-- Opening memberships_update to `user_id = auth.uid()` would have let a manager
-- set their own role to owner, which is the whole of the permission system
-- given away for the sake of a text field. The name is changed through a
-- function instead, which can touch that one column and nothing else.

create or replace function public.set_my_display_name(
  target_agency uuid,
  new_name text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  trimmed text := btrim(new_name);
begin
  if trimmed = '' then
    raise exception 'a name cannot be empty'
      using errcode = 'check_violation';
  end if;
  if length(trimmed) > 120 then
    raise exception 'that name is too long'
      using errcode = 'check_violation';
  end if;

  -- Membership in the agency is the whole of the authorisation: you are
  -- setting your own name, on your own row.
  if not public.is_member(target_agency) then
    raise exception 'not a member of this agency';
  end if;

  update public.memberships
     set full_name = trimmed
   where agency_id = target_agency
     and user_id = auth.uid();
end;
$$;

revoke all on function public.set_my_display_name from public;
grant execute on function public.set_my_display_name to authenticated;

comment on function public.set_my_display_name is
  'Sets the caller''s own display name. Cannot reach role, or anyone else''s row.';

-- ------------------------------------------------- who owns the agency record
-- The agency's name and its WhatsApp number are its identity: the name on a
-- receipt, and the number a tenant replies to. Someone invited to help manage
-- the portfolio has no business changing either. Managers keep every other
-- permission they had; this narrows one table.

drop policy if exists agencies_update on agencies;
drop policy if exists agencies_update on agencies;
create policy agencies_update on agencies for update
  using (public.has_role(id, array['owner']::member_role[]))
  with check (public.has_role(id, array['owner']::member_role[]));

-- ======================================================================
-- 20260808121400_advance_payments_and_proof.sql
-- ======================================================================

-- Charta Home · rent paid ahead, and the paper that proves it
--
-- Two gaps in how money is recorded.
--
-- A tenant paying six months up front is ordinary here, and it did not work.
-- record_payment created the charge for the day of payment and then allocated
-- against whatever was open, so the surplus had nowhere to go: the payment was
-- recorded at its full amount, the tenant's next five months still read as
-- unpaid, and the difference sat in the payments table matching nothing. The
-- money was never lost, but the schedule lied.
--
-- And with no card processing, the proof of a payment is a photograph of a
-- deposit slip or an Orange Money confirmation. There was nowhere to keep it,
-- so the record said 1 200 000 GNF received and could not say how anyone knew.

alter table payments add column if not exists proof_path text;

comment on column payments.proof_path is
  'Storage object in the receipts bucket: the slip or screenshot behind this payment.';

-- ------------------------------------------------------ one period forward
-- The step depends on the lease, so it lives next to the charge generator
-- rather than being spelled out at each call site.
create or replace function public.next_period_start(
  from_period date,
  cycle_in lease_cycle
)
returns date
language sql
immutable
set search_path = ''
as $$
  select case cycle_in::text
    when 'daily'     then from_period + 1
    when 'quarterly' then (from_period + interval '3 months')::date
    when 'yearly'    then (from_period + interval '1 year')::date
    else                  (from_period + interval '1 month')::date
  end;
$$;

-- --------------------------------------------------------- record a payment
-- Dropped rather than replaced: adding parameters to the existing signature
-- would leave two overloads, and a later `grant execute on function
-- public.record_payment` would then be ambiguous.
drop function if exists public.record_payment(uuid, bigint, payment_method, date, text);

/**
 * Records money received and settles what it covers.
 *
 * periods_covered says how far forward the payment reaches. One is the normal
 * case and keeps the old behaviour exactly. Six creates the next five periods
 * before allocating, so a tenant who has paid the year reads as paid for the
 * year rather than as five months in arrears.
 *
 * Allocation is still oldest first, so arrears are cleared before anything is
 * put towards a period that has not arrived. An agency settling a debt and
 * paying ahead in one transfer does not have to split it themselves.
 */
create or replace function public.record_payment(
  target_lease uuid,
  payment_amount bigint,
  payment_method_in payment_method default 'cash',
  paid_on_in date default current_date,
  reference_in text default null,
  periods_covered integer default 1,
  proof_path_in text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  l record;
  new_payment uuid;
  remaining bigint := payment_amount;
  c record;
  take bigint;
  period_cursor date;
  i integer;
  span integer;
begin
  if payment_amount <= 0 then
    raise exception 'payment amount must be positive';
  end if;

  select * into l from public.leases where id = target_lease;
  if not found then
    raise exception 'lease % not found', target_lease;
  end if;
  if not public.has_role(l.agency_id, array['owner', 'manager', 'accountant']::public.member_role[]) then
    raise exception 'not allowed to record payments for this agency';
  end if;

  -- A daily let paid a year ahead is 365 periods, so the ceiling is generous.
  -- It exists to stop a typo in a number field writing rows until it times out.
  span := least(greatest(coalesce(periods_covered, 1), 1), 400);

  insert into public.payments
    (agency_id, lease_id, amount, paid_on, method, reference, proof_path, recorded_by)
  values
    (l.agency_id, l.id, payment_amount, paid_on_in, payment_method_in, reference_in,
     nullif(btrim(coalesce(proof_path_in, '')), ''), auth.uid())
  returning id into new_payment;

  -- Every period this payment reaches has to exist before it can be settled.
  -- ensure_rent_charge is idempotent on (lease, period start), so a period
  -- already raised is left alone.
  period_cursor := paid_on_in;
  for i in 1..span loop
    -- A fixed term lease is not billed past its end.
    exit when l.ends_on is not null and period_cursor > l.ends_on;
    perform public.ensure_rent_charge(l.id, period_cursor);
    period_cursor := public.next_period_start(period_cursor, l.cycle);
  end loop;

  for c in
    select cs.rent_charge_id, cs.balance
    from public.v_charge_status cs
    where cs.lease_id = l.id and cs.balance > 0 and cs.state <> 'void'
    order by cs.period_start asc
  loop
    exit when remaining <= 0;
    take := least(remaining, c.balance);

    insert into public.payment_allocations (payment_id, rent_charge_id, agency_id, amount)
    values (new_payment, c.rent_charge_id, l.agency_id, take)
    on conflict (payment_id, rent_charge_id)
      do update set amount = public.payment_allocations.amount + excluded.amount;

    remaining := remaining - take;
  end loop;

  -- Mark fully settled charges so reminder jobs can skip them cheaply.
  update public.rent_charges rc
     set status = 'paid'
   where rc.lease_id = l.id
     and rc.status <> 'void'
     and exists (
       select 1 from public.v_charge_status cs
        where cs.rent_charge_id = rc.id and cs.balance <= 0
     );

  return new_payment;
end;
$$;

grant execute on function public.record_payment to authenticated;
grant execute on function public.next_period_start to authenticated;

-- ======================================================================
-- 20260808121500_whatsapp_conversation_state.sql
-- ======================================================================

-- Charta Home · remembering where a WhatsApp conversation got to
--
-- The webhook could do exactly one thing: turn a single message into a ticket.
-- That is not how anybody reports a problem. A real report arrives as
--
--   "bonjour"
--   "le robinet de la salle de bain fuit"
--   [photo]
--
-- which opened three tickets, one of them called "bonjour", and lost the
-- photograph. And a tenant on two leases could not be placed at all, because
-- there was no way to ask which flat and no way to remember having asked.
--
-- So the conversation carries a state. It is deliberately small: a tenant
-- should not be walked through a menu to say a tap is leaking.

alter table wa_conversations
  add column if not exists state text not null default 'idle'
    check (state in ('idle', 'awaiting_apartment')),
  -- The report a tenant already typed, held while we ask which flat it is
  -- about, so they never have to write it twice.
  add column if not exists pending_report text,
  -- Further messages join this ticket instead of opening another.
  add column if not exists active_ticket_id uuid references tickets (id) on delete set null,
  add column if not exists state_changed_at timestamptz not null default now();

comment on column wa_conversations.state is
  'idle, or awaiting_apartment when the tenant has been asked which unit.';
comment on column wa_conversations.active_ticket_id is
  'Recent open ticket. Follow up messages attach here rather than duplicating.';

-- ------------------------------------------------------- follow up window
-- How long a message is treated as part of the report before it rather than
-- as a new one. A photograph sent a minute later is plainly the same subject;
-- a message the following week is plainly not.
create or replace function public.wa_followup_window()
returns interval
language sql
immutable
set search_path = ''
as $$ select interval '6 hours' $$;

/**
 * Where an inbound message should go.
 *
 * Returns the conversation row with a decision attached, so the webhook makes
 * one round trip instead of four and cannot drift out of step with itself.
 *
 * The decision is one of:
 *   attach  - add to active_ticket_id, the tenant is still describing
 *   ask     - more than one lease, and we do not know which flat
 *   answer  - they were asked, this message names the flat
 *   open    - a new report, one lease, go ahead
 *   unknown - the number is not a tenant of this agency
 */
create or replace function public.wa_route_inbound(
  from_phone text,
  body text
)
-- The output names deliberately avoid agency_id, resident_id and
-- pending_report. Those are columns on wa_conversations, and an OUT parameter
-- sharing a name with a column makes every mention of it inside the body
-- ambiguous, including the one in `on conflict (agency_id, phone_e164)`.
returns table (
  conversation_id uuid,
  agency uuid,
  resident uuid,
  resident_name text,
  decision text,
  ticket_id uuid,
  report text,
  lease_count integer
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  r record;
  conv record;
  leases integer;
begin
  -- A phone number is the identity. It is the one thing a tenant cannot
  -- forget, mistype under stress, or need to be told twice, which is why
  -- nothing here asks for a reference number.
  select res.id, res.agency_id, res.full_name
    into r
    from public.residents res
   where res.phone_e164 = from_phone
   limit 1;

  if not found then
    return query select null::uuid, null::uuid, null::uuid, null::text,
                        'unknown'::text, null::uuid, null::text, 0;
    return;
  end if;

  select count(*)::integer into leases
    from public.leases l
   where l.resident_id = r.id and l.status = 'active';

  insert into public.wa_conversations (agency_id, phone_e164, resident_id, last_inbound_at)
  values (r.agency_id, from_phone, r.id, now())
  on conflict (agency_id, phone_e164) do update
    set last_inbound_at = now(), resident_id = excluded.resident_id
  returning * into conv;

  -- Asked which flat, and this is the reply.
  if conv.state = 'awaiting_apartment' then
    return query select conv.id, r.agency_id, r.id, r.full_name,
                        'answer'::text, null::uuid, conv.pending_report, leases;
    return;
  end if;

  -- Still talking about something opened a moment ago.
  if conv.active_ticket_id is not null
     and conv.state_changed_at > now() - public.wa_followup_window()
     and exists (
       select 1 from public.tickets t
        where t.id = conv.active_ticket_id and t.status <> 'resolved'
     )
  then
    return query select conv.id, r.agency_id, r.id, r.full_name,
                        'attach'::text, conv.active_ticket_id, null::text, leases;
    return;
  end if;

  if leases = 0 then
    return query select conv.id, r.agency_id, r.id, r.full_name,
                        'unknown'::text, null::uuid, null::text, 0;
  elsif leases > 1 then
    return query select conv.id, r.agency_id, r.id, r.full_name,
                        'ask'::text, null::uuid, body, leases;
  else
    return query select conv.id, r.agency_id, r.id, r.full_name,
                        'open'::text, null::uuid, body, leases;
  end if;
end;
$$;

revoke all on function public.wa_route_inbound from public;

/** Records what the webhook decided, so the next message lands correctly. */
create or replace function public.wa_set_state(
  conversation uuid,
  new_state text,
  report text default null,
  ticket uuid default null
)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.wa_conversations
     set state = new_state,
         pending_report = report,
         active_ticket_id = coalesce(ticket, active_ticket_id),
         state_changed_at = now()
   where id = conversation;
$$;

revoke all on function public.wa_set_state from public;

-- ======================================================================
-- 20260808121600_member_page_access.sql
-- ======================================================================

-- Charta Home · which pages a colleague sees
--
-- Roles decide what somebody may do to the data, and row level security
-- enforces that. What they did not decide is what somebody is shown. A
-- caretaker who only ever fixes taps was handed the whole dashboard, rent
-- collection included, and had to know for themselves which parts were not
-- their business.
--
-- This is navigation, not security. It is written down here rather than in the
-- interface so the server can honour it too: hiding a link while leaving the
-- route open is theatre, and the route is closed in the dashboard layout using
-- exactly this column. The data underneath stays guarded by RLS either way,
-- which is the difference between a menu that is tidy and a rule that holds.

-- The four working pages. Settings is deliberately absent: it is where a
-- person sets their own name, and its agency fields are already owner only,
-- so removing it would only strand somebody with a misspelled name.
create or replace function public.default_pages_for_role(r member_role)
returns text[]
language sql
immutable
set search_path = ''
as $$
  select case r
    when 'owner'      then array['dashboard', 'apartments', 'rent', 'maintenance']
    when 'manager'    then array['dashboard', 'apartments', 'rent', 'maintenance']
    -- Money, and the portfolio it comes from. Not the repairs.
    when 'accountant' then array['dashboard', 'rent']
    -- The jobs, and the units they are in. Not what anybody pays.
    when 'caretaker'  then array['dashboard', 'maintenance']
    else array['dashboard']
  end;
$$;

alter table memberships
  add column if not exists allowed_pages text[];

-- Everyone already in an agency keeps what their role implies, so nobody
-- loses a page they were using this morning.
update memberships
   set allowed_pages = public.default_pages_for_role(role)
 where allowed_pages is null;

-- No column default: a fixed one would give every new colleague the same
-- menu whatever they were hired to do, which is how a caretaker ended up
-- with nothing but the dashboard. The trigger below fills it from the role
-- instead, and runs before the not null check.
alter table memberships
  alter column allowed_pages drop default,
  alter column allowed_pages set not null;

create or replace function public.membership_default_pages()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.allowed_pages is null then
    new.allowed_pages := public.default_pages_for_role(new.role);
  end if;
  return new;
end;
$$;

drop trigger if exists memberships_default_pages on memberships;
drop trigger if exists memberships_default_pages on memberships;
create trigger memberships_default_pages
  before insert on memberships
  for each row execute function public.membership_default_pages();

-- A page name that does not exist would silently hide a link, so the set is
-- closed rather than free text.
alter table memberships
  drop constraint if exists memberships_allowed_pages_known;
alter table memberships drop constraint if exists memberships_allowed_pages_known;
alter table memberships
  add constraint memberships_allowed_pages_known
  check (allowed_pages <@ array['dashboard', 'apartments', 'rent', 'maintenance']);

comment on column memberships.allowed_pages is
  'Sidebar pages this member may open. Navigation only: RLS still guards the data.';

/**
 * Sets what a colleague may see.
 *
 * Owner only, and it cannot reach role, so the one function an owner uses to
 * tidy a menu can never be the one that quietly promotes somebody. An owner
 * cannot narrow their own view either, which would otherwise be a way to lock
 * the last owner out of the agency's own settings.
 */
create or replace function public.set_member_pages(
  target_agency uuid,
  target_user uuid,
  pages text[]
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.has_role(target_agency, array['owner']::public.member_role[]) then
    raise exception 'only the owner can change what a colleague sees';
  end if;

  if target_user = auth.uid() then
    raise exception 'an owner cannot restrict their own access';
  end if;

  update public.memberships
     set allowed_pages = coalesce(pages, array['dashboard'])
   where agency_id = target_agency
     and user_id = target_user;
end;
$$;

revoke all on function public.set_member_pages from public;
grant execute on function public.set_member_pages to authenticated;
grant execute on function public.default_pages_for_role to authenticated;

-- ------------------------------------------------------- the team roster
-- The roster now has to carry what each colleague may see, so the settings
-- page can show it and change it. Dropped and recreated because the return
-- type is changing, which `create or replace` will not do.
drop function if exists public.list_agency_members(uuid);

create or replace function public.list_agency_members(target_agency uuid)
returns table (
  user_id       uuid,
  full_name     text,
  role          public.member_role,
  email         text,
  allowed_pages text[],
  created_at    timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_member(target_agency) then
    raise exception 'not a member of this agency';
  end if;

  return query
    select m.user_id, m.full_name, m.role, u.email::text, m.allowed_pages, m.created_at
    from public.memberships m
    join auth.users u on u.id = m.user_id
    where m.agency_id = target_agency
    order by m.created_at;
end;
$$;

grant execute on function public.list_agency_members to authenticated;

comment on function public.list_agency_members is
  'The settings team roster, email and page access included. Raises unless the caller belongs to the agency.';

-- ======================================================================
-- 20260808121700_semester_lease_cycle.sql
-- ======================================================================

-- Charta Home · six month leases
--
-- Half yearly terms are common where a tenant pays around a harvest or a
-- school year, and there was no way to record one: it had to be entered as
-- two quarters or as a year that was not a year.

alter type lease_cycle add value if not exists 'semester';

-- ----------------------------------------------------------- one step on
create or replace function public.next_period_start(
  from_period date,
  cycle_in lease_cycle
)
returns date
language sql
immutable
set search_path = ''
as $$
  select case cycle_in::text
    when 'daily'     then from_period + 1
    when 'quarterly' then (from_period + interval '3 months')::date
    when 'semester'  then (from_period + interval '6 months')::date
    when 'yearly'    then (from_period + interval '1 year')::date
    else                  (from_period + interval '1 month')::date
  end;
$$;

grant execute on function public.next_period_start to authenticated;

-- --------------------------------------------------------- charge generation
-- A semester is the first cycle whose period does not line up with a date_trunc
-- unit, so it is worked out from the year: January to June, or July to
-- December. That keeps two tenants on the same building billed for the same
-- two halves, rather than each on their own six month drift.
create or replace function public.ensure_rent_charge(
  target_lease uuid,
  period date
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  l record;
  start_on date;
  end_on date;
  due date;
  charge_id uuid;
begin
  select * into l from public.leases where id = target_lease;
  if not found then
    raise exception 'lease % not found', target_lease;
  end if;
  if not public.is_member(l.agency_id) then
    raise exception 'not a member of this agency';
  end if;

  if l.cycle::text = 'yearly' then
    start_on := date_trunc('year', period)::date;
    end_on := (date_trunc('year', period) + interval '1 year - 1 day')::date;
  elsif l.cycle::text = 'semester' then
    start_on := (date_trunc('year', period)
                 + make_interval(months => case when extract(month from period) <= 6 then 0 else 6 end))::date;
    end_on := (start_on + interval '6 months - 1 day')::date;
  elsif l.cycle::text = 'quarterly' then
    start_on := date_trunc('quarter', period)::date;
    end_on := (date_trunc('quarter', period) + interval '3 months - 1 day')::date;
  elsif l.cycle::text = 'daily' then
    start_on := period;
    end_on := period;
  else
    start_on := date_trunc('month', period)::date;
    end_on := (date_trunc('month', period) + interval '1 month - 1 day')::date;
  end if;

  -- A day long charge is due that day. Offsetting by due_day would push it
  -- past the end of the period it bills for.
  if l.cycle::text = 'daily' then
    due := start_on;
  else
    due := (start_on + (l.due_day - 1) * interval '1 day')::date;
  end if;

  insert into public.rent_charges (agency_id, lease_id, period_start, period_end, amount, due_on)
  values (l.agency_id, l.id, start_on, end_on, l.rent_amount, due)
  on conflict (lease_id, period_start) do nothing
  returning id into charge_id;

  if charge_id is null then
    select id into charge_id
    from public.rent_charges
    where lease_id = l.id and period_start = start_on;
  end if;

  return charge_id;
end;
$$;

grant execute on function public.ensure_rent_charge to authenticated;

-- ------------------------------------------------- money with nowhere to go
-- Recording a payment for a tenant who is already straight allocated nothing:
-- the only period it could reach was the current one, and that was settled.
-- The payment was stored at its full amount and matched no month at all, so
-- the money was in the books and invisible on the schedule.
--
-- A tenant who is paid up and hands over more is paying ahead, so the periods
-- are raised as the money needs them rather than only the ones asked for. The
-- loop is bounded, and stops at the end of a fixed term lease.
create or replace function public.record_payment(
  target_lease uuid,
  payment_amount bigint,
  payment_method_in payment_method default 'cash',
  paid_on_in date default current_date,
  reference_in text default null,
  periods_covered integer default 1,
  proof_path_in text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  l record;
  new_payment uuid;
  remaining bigint := payment_amount;
  c record;
  take bigint;
  period_cursor date;
  i integer;
  span integer;
  next_charge uuid;
begin
  if payment_amount <= 0 then
    raise exception 'payment amount must be positive';
  end if;

  select * into l from public.leases where id = target_lease;
  if not found then
    raise exception 'lease % not found', target_lease;
  end if;
  if not public.has_role(l.agency_id, array['owner', 'manager', 'accountant']::public.member_role[]) then
    raise exception 'not allowed to record payments for this agency';
  end if;

  -- A daily let paid a year ahead is 365 periods, so the ceiling is generous.
  -- It exists to stop a typo in a number field writing rows until it times out.
  span := least(greatest(coalesce(periods_covered, 1), 1), 400);

  insert into public.payments
    (agency_id, lease_id, amount, paid_on, method, reference, proof_path, recorded_by)
  values
    (l.agency_id, l.id, payment_amount, paid_on_in, payment_method_in, reference_in,
     nullif(btrim(coalesce(proof_path_in, '')), ''), auth.uid())
  returning id into new_payment;

  period_cursor := paid_on_in;
  for i in 1..span loop
    exit when l.ends_on is not null and period_cursor > l.ends_on;
    perform public.ensure_rent_charge(l.id, period_cursor);
    period_cursor := public.next_period_start(period_cursor, l.cycle);
  end loop;

  -- Oldest first, so arrears clear before anything goes towards a period that
  -- has not arrived.
  for c in
    select cs.rent_charge_id, cs.balance
    from public.v_charge_status cs
    where cs.lease_id = l.id and cs.balance > 0 and cs.state <> 'void'
    order by cs.period_start asc
  loop
    exit when remaining <= 0;
    take := least(remaining, c.balance);

    insert into public.payment_allocations (payment_id, rent_charge_id, agency_id, amount)
    values (new_payment, c.rent_charge_id, l.agency_id, take)
    on conflict (payment_id, rent_charge_id)
      do update set amount = public.payment_allocations.amount + excluded.amount;

    remaining := remaining - take;
  end loop;

  -- Still money left, which means every period that exists is settled. Raise
  -- the next one and put it there, until the money runs out.
  if remaining > 0 then
    select max(period_start) into period_cursor
      from public.rent_charges where lease_id = l.id;
    period_cursor := coalesce(period_cursor, paid_on_in);

    for i in 1..400 loop
      exit when remaining <= 0;
      period_cursor := public.next_period_start(period_cursor, l.cycle);
      exit when l.ends_on is not null and period_cursor > l.ends_on;

      next_charge := public.ensure_rent_charge(l.id, period_cursor);
      exit when next_charge is null;

      select cs.balance into take
        from public.v_charge_status cs where cs.rent_charge_id = next_charge;
      if take is null or take <= 0 then
        continue;
      end if;
      take := least(remaining, take);

      insert into public.payment_allocations (payment_id, rent_charge_id, agency_id, amount)
      values (new_payment, next_charge, l.agency_id, take)
      on conflict (payment_id, rent_charge_id)
        do update set amount = public.payment_allocations.amount + excluded.amount;

      remaining := remaining - take;
    end loop;
  end if;

  update public.rent_charges rc
     set status = 'paid'
   where rc.lease_id = l.id
     and rc.status <> 'void'
     and exists (
       select 1 from public.v_charge_status cs
        where cs.rent_charge_id = rc.id and cs.balance <= 0
     );

  return new_payment;
end;
$$;

grant execute on function public.record_payment to authenticated;

-- ======================================================================
-- 20260808121800_lease_tenant_identity.sql
-- ======================================================================

-- Charta Home · the tenant you typed is the tenant you get
--
-- Adding a tenant to a flat showed somebody else's name. create_lease looked
-- for a resident with the same phone number, and when it found one it reused
-- that row and dropped the name that had just been typed on the floor. So an
-- agency entering a new tenant with a number already in the book got the
-- previous tenant's name on the lease, with nothing said about it.
--
-- The number is still the identity, and it has to be: the WhatsApp webhook
-- finds a tenant by the number they message from, and two residents sharing
-- one number would make that ambiguous. What changes is that the name is not
-- silently discarded. The agency has just said what this person is called, so
-- the record is brought into line with what they said.
--
-- And a blank phone became the empty string, which the column's own check
-- refuses, so a tenant without a number could not be added at all. Blank now
-- means null, which is what "we do not have a number for them" is stored as.

create or replace function public.create_lease(
  target_apartment uuid,
  resident_name text,
  resident_phone text,
  rent bigint,
  cycle_in lease_cycle default 'monthly',
  starts_on_in date default current_date,
  deposit_in bigint default 0,
  ends_on_in date default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  ap record;
  resident uuid;
  existing_name text;
  new_lease uuid;
  clean_name text := btrim(coalesce(resident_name, ''));
  clean_phone text := nullif(btrim(coalesce(resident_phone, '')), '');
begin
  select * into ap from public.apartments where id = target_apartment;
  if not found then
    raise exception 'apartment % not found', target_apartment;
  end if;
  if not public.has_role(ap.agency_id, array['owner', 'manager']::public.member_role[]) then
    raise exception 'not allowed to create leases for this agency';
  end if;

  if clean_name = '' then
    raise exception 'a tenant needs a name'
      using errcode = 'check_violation';
  end if;

  -- A move out date before the move in date is a typo, not a lease.
  if ends_on_in is not null and ends_on_in < starts_on_in then
    raise exception 'lease cannot end before it starts';
  end if;

  -- Only look for an existing tenant when there is a number to look them up
  -- by. Without one, every tenant with no phone would collapse into whichever
  -- of them was entered first.
  if clean_phone is not null then
    select id, full_name into resident, existing_name
    from public.residents
    where agency_id = ap.agency_id and phone_e164 = clean_phone
    limit 1;
  end if;

  if resident is null then
    insert into public.residents (agency_id, full_name, phone_e164)
    values (ap.agency_id, clean_name, clean_phone)
    returning id into resident;
  elsif existing_name is distinct from clean_name then
    -- Same number, different name. Believe the person entering it: they are
    -- looking at the tenancy agreement, and this is the only place the name
    -- can be corrected without hunting for the tenant first.
    update public.residents set full_name = clean_name where id = resident;
  end if;

  insert into public.leases (
    agency_id, apartment_id, resident_id, cycle, rent_amount, deposit,
    starts_on, ends_on, status
  )
  values (
    ap.agency_id, ap.id, resident, cycle_in, rent, deposit_in,
    starts_on_in, ends_on_in, 'active'
  )
  returning id into new_lease;

  perform public.ensure_rent_charge(new_lease, starts_on_in);

  return new_lease;
end;
$$;

grant execute on function public.create_lease to authenticated;

/**
 * Who a phone number already belongs to, within the caller's own agency.
 *
 * So the lease form can say "this number is already on file for Beatrice
 * Tiomela" while it is being typed, rather than the agency discovering it
 * after the fact by reading a name they did not enter. Returns nothing when
 * the number is free, and is scoped by membership like everything else.
 */
create or replace function public.resident_by_phone(
  target_agency uuid,
  phone text
)
returns table (resident_id uuid, full_name text)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  clean_phone text := nullif(btrim(coalesce(phone, '')), '');
begin
  if not public.is_member(target_agency) then
    raise exception 'not a member of this agency';
  end if;
  if clean_phone is null then
    return;
  end if;

  return query
    select r.id, r.full_name
    from public.residents r
    where r.agency_id = target_agency and r.phone_e164 = clean_phone
    limit 1;
end;
$$;

grant execute on function public.resident_by_phone to authenticated;

-- ======================================================================
-- 20260808121900_agency_details_for_receipts.sql
-- ======================================================================

-- Charta Home · an agency's own details on its own receipts
--
-- The printed receipt carried a street address, an email and a registration
-- number that belonged to nobody: they were demo values in the interface, and
-- every agency's receipt showed the same fabricated ones. A receipt is a
-- document a tenant keeps and may produce later, so putting another company's
-- address and an invented RCCM number on it is worse than leaving them off.
--
-- These are the fields a receipt actually needs and the agencies table did not
-- carry. All optional: an agency that has not filled them in gets a receipt
-- without those lines, rather than a receipt with somebody else's.

alter table agencies
  add column if not exists address text,
  add column if not exists email citext,
  add column if not exists registration text;

comment on column agencies.address is
  'Street address as it should appear on a receipt.';
comment on column agencies.registration is
  'Company registration, RCCM in Guinea. Printed on receipts when present.';

-- ======================================================================
-- 20260808122000_apartment_performance.sql
-- ======================================================================

-- Charta Home · what a flat actually returned
--
-- The apartment page showed a "net yield" that was the building's figure
-- repeated on every unit in it, so two flats with very different histories
-- read identically. And the dashboard invented two of its four tiles outright:
-- service charges were rent times 0.08, and maintenance was the building's
-- expenses divided by eight. Both were plausible looking numbers that nothing
-- in the database supported, on a screen an agency uses to decide things.
--
-- This is the per unit equivalent of v_building_performance: money actually
-- received against money actually spent on that unit, for the current year.
-- Expenses recorded against the building rather than a flat are deliberately
-- not spread across its flats, because apportioning a roof repair by guesswork
-- would put a number on the screen that nobody could check.

create or replace view v_apartment_performance
with (security_invoker = true)
as
select
  ap.id                                        as apartment_id,
  ap.agency_id,
  ap.building_id,
  coalesce(collected.total, 0)::bigint         as collected_ytd,
  coalesce(spent.total, 0)::bigint             as expenses_ytd,
  (coalesce(collected.total, 0) - coalesce(spent.total, 0))::bigint as net_ytd,
  -- What is left of the rent after what the flat cost to keep. Null rather
  -- than zero when nothing has been collected: a unit that has taken no money
  -- has no margin, and showing 0% would read as one that broke even.
  case
    when coalesce(collected.total, 0) > 0
      then round(
        ((coalesce(collected.total, 0) - coalesce(spent.total, 0))::numeric
          / collected.total) * 100,
        1
      )
    else null
  end                                          as net_margin_pct
from apartments ap
left join lateral (
  select sum(p.amount) as total
  from payments p
  join leases l on l.id = p.lease_id
  where l.apartment_id = ap.id
    and p.paid_on >= date_trunc('year', current_date)
) collected on true
left join lateral (
  select sum(e.amount) as total
  from expenses e
  where e.apartment_id = ap.id
    and e.incurred_on >= date_trunc('year', current_date)
) spent on true;

comment on view v_apartment_performance is
  'Per unit money in and money out for the current year. Building level expenses are not apportioned.';

-- ======================================================================
-- 20260808122100_pricing_plans.sql
-- ======================================================================

-- Charta Home · the pricing model
--
-- Five tiers, priced per country, sized by the number of apartments an agency
-- manages. That count is the only thing a tier restricts: an agency on Starter
-- can run as many buildings and colleagues as it likes, up to thirty flats.
--
-- What was here before was three rows keyed by an enum and priced in dollars
-- that nobody in Conakry or Douala pays in, gating buildings and team members
-- the product never actually gated. The enum stays as it is. Postgres allows
-- a new enum value inside a transaction but refuses to use it as a literal in
-- the same one, and this whole file is pasted as one transaction; a catalogue
-- table has no such rule, and a sixth tier one day is an insert rather than a
-- type change.
--
-- Prices are whole francs. GNF and XAF have no minor unit, so the smallest
-- unit and the franc are the same number.

-- ------------------------------------------------------------ the tiers
create table if not exists plans (
  code           text primary key,
  rank           smallint not null,
  min_apartments integer not null check (min_apartments >= 1),
  -- null is no ceiling at all
  max_apartments integer check (max_apartments is null or max_apartments >= min_apartments)
);

comment on table plans is
  'The five tiers. A tier is a band of managed apartments; nothing else is restricted.';

insert into plans (code, rank, min_apartments, max_apartments) values
  ('starter',    1,   1,  30),
  ('growth',     2,  31,  50),
  ('pro',        3,  51, 100),
  ('business',   4, 101, 250),
  ('enterprise', 5, 251, null)
on conflict (code) do update
  set rank           = excluded.rank,
      min_apartments = excluded.min_apartments,
      max_apartments = excluded.max_apartments;

-- ----------------------------------------------------------- the prices
-- One row per tier per country. A null price is a quote: Enterprise is priced
-- by conversation, and a country with no list yet gets no row at all.
create table if not exists plan_prices (
  plan     text not null references plans (code) on delete cascade,
  country  text not null,
  currency char(3) not null,
  monthly  bigint check (monthly is null or monthly > 0),
  annual   bigint check (annual is null or annual > 0),
  primary key (plan, country)
);

comment on table plan_prices is
  'Whole francs, per tier and country. Annual is ten months for twelve.';

insert into plan_prices (plan, country, currency, monthly, annual) values
  ('starter',    'Guinea',   'GNF', 175000, 1750000),
  ('growth',     'Guinea',   'GNF', 450000, 4500000),
  ('pro',        'Guinea',   'GNF', 500000, 5000000),
  ('business',   'Guinea',   'GNF', 850000, 8500000),
  ('enterprise', 'Guinea',   'GNF', null,   null),
  ('starter',    'Cameroon', 'XAF',  12000,  120000),
  ('growth',     'Cameroon', 'XAF',  30000,  300000),
  ('pro',        'Cameroon', 'XAF',  50000,  500000),
  ('business',   'Cameroon', 'XAF',  55000,  550000),
  ('enterprise', 'Cameroon', 'XAF', null,   null)
on conflict (plan, country) do update
  set currency = excluded.currency,
      monthly  = excluded.monthly,
      annual   = excluded.annual;

-- The price list is public: the marketing page reads it before anyone signs
-- in. Nothing but the service role writes it.
alter table plans       enable row level security;
alter table plan_prices enable row level security;

drop policy if exists plans_select on plans;
create policy plans_select       on plans       for select using (true);
drop policy if exists plan_prices_select on plan_prices;
create policy plan_prices_select on plan_prices for select using (true);

-- ---------------------------------------------- the subscription's plan
-- From the enum to the catalogue. Done once, and only while the column is
-- still the enum, so a second paste of this file finds nothing to do. The
-- one tier that changed its name is carried across.
do $$
begin
  if exists (
    select 1
    from pg_attribute a
    join pg_class c on c.oid = a.attrelid
    join pg_namespace n on n.oid = c.relnamespace
    join pg_type t on t.oid = a.atttypid
    where n.nspname = 'public'
      and c.relname = 'subscriptions'
      and a.attname = 'plan'
      and t.typname = 'plan_tier'
  ) then
    alter table public.subscriptions alter column plan drop default;
    alter table public.subscriptions
      alter column plan type text
      using (case plan::text when 'agency' then 'enterprise' else plan::text end);
    alter table public.subscriptions alter column plan set default 'growth';
  end if;
end $$;

alter table subscriptions drop constraint if exists subscriptions_plan_fkey;
alter table subscriptions drop constraint if exists subscriptions_plan_fkey;
alter table subscriptions
  add constraint subscriptions_plan_fkey foreign key (plan) references plans (code);

-- An owner could update their own subscription row, which meant an owner
-- could set plan = 'enterprise' with one API call. Now that the plan is what
-- they pay for, only the service role moves it, once the money has arrived.
drop policy if exists subscriptions_update on subscriptions;

-- ------------------------------------------------ the old limits, gone
-- Buildings and members are no longer restricted, and the dollar list is
-- replaced by plan_prices. The table can go once nothing reads it.
drop trigger if exists buildings_plan_limit on buildings;
drop function if exists public.enforce_building_limit();
drop table if exists plan_limits;

-- ------------------------------------------------- the one restriction
-- Counted across the agency rather than the building, because the tier is
-- the agency's. An agency with no subscription row has no ceiling, which can
-- only be reached through the service role.
create or replace function public.enforce_apartment_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  ceiling integer;
  used integer;
  plan_code text;
begin
  select s.plan, p.max_apartments
    into plan_code, ceiling
  from public.subscriptions s
  join public.plans p on p.code = s.plan
  where s.agency_id = new.agency_id;

  if ceiling is null then
    return new;
  end if;

  select count(*) into used from public.apartments where agency_id = new.agency_id;

  if used >= ceiling then
    raise exception 'plan limit reached: % apartments allowed on the % plan', ceiling, plan_code
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

drop trigger if exists apartments_plan_limit on apartments;
create trigger apartments_plan_limit before insert on apartments
  for each row execute function public.enforce_apartment_limit();

-- ------------------------------------------------- signup picks a tier
-- The pricing page carries the chosen tier into signup. The old signature is
-- dropped rather than overloaded, because a six argument call would match
-- both and Postgres would refuse to choose.
drop function if exists public.create_agency_for_current_user(text, text, text, char, text, text);

create or replace function public.create_agency_for_current_user(
  agency_name text,
  agency_country text default 'Guinea',
  agency_city text default 'Conakry',
  agency_currency char(3) default 'GNF',
  agency_locale text default 'fr',
  owner_name text default null,
  plan_code text default 'growth'
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  new_agency uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not exists (select 1 from public.plans where code = plan_code) then
    raise exception 'unknown plan %', plan_code;
  end if;

  insert into public.agencies (name, country, city, currency, locale)
  values (agency_name, agency_country, agency_city, agency_currency, agency_locale)
  returning id into new_agency;

  insert into public.memberships (user_id, agency_id, role, full_name)
  values (auth.uid(), new_agency, 'owner', owner_name);

  insert into public.subscriptions (agency_id, plan, status)
  values (new_agency, plan_code, 'trialing');

  insert into public.reminder_rules (agency_id, offset_days, channel, escalation_step) values
    (new_agency, -3, 'whatsapp', 0),
    (new_agency,  0, 'whatsapp', 0),
    (new_agency,  5, 'whatsapp', 1),
    (new_agency, 10, 'whatsapp', 2);

  return new_agency;
end;
$$;

revoke all on function public.create_agency_for_current_user from public;
grant execute on function public.create_agency_for_current_user to authenticated;

-- ---------------------------------------------------- asking for a plan
-- There is no card form yet. An owner picks a tier and a cycle, the request
-- is recorded here, the team is emailed, and the agency pays by mobile money.
-- The team marks the row paid and moves the subscription; until then the
-- request is what the settings page shows.
create table if not exists plan_requests (
  id           uuid primary key default gen_random_uuid(),
  agency_id    uuid not null references agencies (id) on delete cascade,
  plan         text not null references plans (code),
  cycle        text not null check (cycle in ('monthly', 'annual')),
  currency     char(3) not null,
  -- null is a quote to be agreed
  amount       bigint check (amount is null or amount > 0),
  status       text not null default 'pending' check (status in ('pending', 'paid', 'cancelled')),
  requested_by uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now()
);

create index if not exists plan_requests_agency_idx on plan_requests (agency_id, created_at desc);

alter table plan_requests enable row level security;

-- Members read their own agency's requests. Nobody inserts directly: the
-- function below does, so the amount on the row is always the list price.
drop policy if exists plan_requests_select on plan_requests;
create policy plan_requests_select on plan_requests for select
  using (agency_id in (select public.current_agency_ids()));

-- The output names avoid currency and amount on purpose. Those are columns of
-- plan_requests, and an OUT parameter sharing a name with a column makes every
-- mention of it inside the body ambiguous.
create or replace function public.request_plan(
  target_agency uuid,
  plan_code text,
  cycle_in text
)
returns table (request_id uuid, paid_in char(3), due bigint)
language plpgsql
security definer
set search_path = ''
as $$
declare
  a record;
  price record;
  money bigint;
begin
  if not public.has_role(target_agency, array['owner']::public.member_role[]) then
    raise exception 'only the owner can choose a plan';
  end if;
  if cycle_in not in ('monthly', 'annual') then
    raise exception 'unknown billing cycle %', cycle_in;
  end if;
  if not exists (select 1 from public.plans where code = plan_code) then
    raise exception 'unknown plan %', plan_code;
  end if;

  select ag.country, ag.currency into a from public.agencies ag where ag.id = target_agency;

  select pp.currency, pp.monthly, pp.annual into price
  from public.plan_prices pp
  where pp.plan = plan_code and pp.country = a.country;

  if not found then
    -- No list for this country yet. Recorded as a quote in the agency's own
    -- currency, so the team knows what to reply in.
    return query
      insert into public.plan_requests (agency_id, plan, cycle, currency, amount, requested_by)
      values (target_agency, plan_code, cycle_in, a.currency, null, auth.uid())
      returning plan_requests.id, plan_requests.currency, plan_requests.amount;
    return;
  end if;

  money := case cycle_in when 'annual' then price.annual else price.monthly end;

  return query
    insert into public.plan_requests (agency_id, plan, cycle, currency, amount, requested_by)
    values (target_agency, plan_code, cycle_in, price.currency, money, auth.uid())
    returning plan_requests.id, plan_requests.currency, plan_requests.amount;
end;
$$;

revoke all on function public.request_plan from public;
grant execute on function public.request_plan to authenticated;

comment on function public.request_plan is
  'Records an owner''s choice of tier and cycle at the list price for the agency''s country. Owner only.';

-- ======================================================================
-- 20260808122200_platform_admin.sql
-- ======================================================================

-- Charta Home · the platform's own desk
--
-- Somebody at Charta Home has to see every agency, what it is on, what it
-- has collected, and turn a mobile money receipt into an active plan. Until
-- now that was a SQL editor. This gives it a table of admins, a view across
-- agencies, and one-time codes, so the flow is: the agency pays and sends
-- the receipt over WhatsApp or email; the desk checks it and issues a code;
-- the owner types the code into settings and the plan is live.
--
-- A code is bound to one agency and one tier, is good for an hour, and dies
-- the moment it is used. Only the owner of that agency can redeem it, so a
-- code read over somebody's shoulder is worth nothing to anyone else.

-- ------------------------------------------------------------ who we are
-- No policies at all: nothing but the service role reads or writes this, and
-- is_platform_admin() answers the one question anybody else needs to ask.
create table if not exists platform_admins (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);

alter table platform_admins enable row level security;

comment on table platform_admins is
  'Charta Home staff. Insert through the service role only; see docs/backend-setup.md.';

create or replace function public.is_platform_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.platform_admins where user_id = auth.uid())
$$;

grant execute on function public.is_platform_admin to authenticated;

-- ------------------------------------------------------- one-time codes
create table if not exists plan_codes (
  id         uuid primary key default gen_random_uuid(),
  code       text not null unique,
  agency_id  uuid not null references agencies (id) on delete cascade,
  plan       text not null references plans (code),
  cycle      text not null check (cycle in ('monthly', 'annual')),
  -- the request this settles, when the desk issued it for one
  request_id uuid references plan_requests (id) on delete set null,
  issued_by  uuid references auth.users (id) on delete set null,
  expires_at timestamptz not null,
  used_at    timestamptz,
  used_by    uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists plan_codes_agency_idx on plan_codes (agency_id, created_at desc);

-- No policies here either. The desk issues through one function and the
-- owner redeems through another; nobody selects from the table.
alter table plan_codes enable row level security;

-- ------------------------------------------------- every agency, at once
-- The output names avoid every column name they are read from. An OUT
-- parameter that shares a name with a column makes every mention of it in
-- the body ambiguous.
create or replace function public.admin_list_agencies()
returns table (
  agency_id          uuid,
  agency_name        text,
  agency_country     text,
  agency_city        text,
  agency_currency    char(3),
  signed_up_at       timestamptz,
  owner_name         text,
  owner_email        text,
  agency_whatsapp    text,
  member_count       integer,
  current_plan       text,
  plan_status        text,
  trial_until        timestamptz,
  period_until       timestamptz,
  apartments_used    integer,
  apartments_max     integer,
  collected_total    bigint,
  collected_year     bigint,
  pending_request_id uuid,
  pending_plan       text,
  pending_cycle      text,
  pending_amount     bigint,
  pending_currency   char(3),
  pending_at         timestamptz,
  open_code          text,
  open_code_until    timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_platform_admin() then
    raise exception 'not a platform admin';
  end if;

  return query
  select
    a.id,
    a.name,
    a.country,
    a.city,
    a.currency,
    a.created_at,
    o.full_name,
    u.email::text,
    a.whatsapp_number,
    (select count(*)::integer from public.memberships m where m.agency_id = a.id),
    s.plan,
    s.status::text,
    s.trial_ends_at,
    s.current_period_end,
    (select count(*)::integer from public.apartments ap where ap.agency_id = a.id),
    p.max_apartments,
    coalesce((select sum(py.amount) from public.payments py where py.agency_id = a.id), 0)::bigint,
    coalesce((select sum(py.amount) from public.payments py
               where py.agency_id = a.id and py.paid_on >= date_trunc('year', current_date)), 0)::bigint,
    pr.id,
    pr.plan,
    pr.cycle,
    pr.amount,
    pr.currency,
    pr.created_at,
    pc.code,
    pc.expires_at
  from public.agencies a
  left join public.subscriptions s on s.agency_id = a.id
  left join public.plans p on p.code = s.plan
  left join lateral (
    select m.user_id, m.full_name
    from public.memberships m
    where m.agency_id = a.id and m.role = 'owner'
    order by m.created_at
    limit 1
  ) o on true
  left join auth.users u on u.id = o.user_id
  left join lateral (
    select r.id, r.plan, r.cycle, r.amount, r.currency, r.created_at
    from public.plan_requests r
    where r.agency_id = a.id and r.status = 'pending'
    order by r.created_at desc
    limit 1
  ) pr on true
  left join lateral (
    select c.code, c.expires_at
    from public.plan_codes c
    where c.agency_id = a.id and c.used_at is null and c.expires_at > now()
    order by c.created_at desc
    limit 1
  ) pc on true
  order by a.created_at desc;
end;
$$;

revoke all on function public.admin_list_agencies from public;
grant execute on function public.admin_list_agencies to authenticated;

-- --------------------------------------------------------- issuing one
create or replace function public.admin_issue_plan_code(
  target_agency uuid,
  plan_code text,
  cycle_in text
)
returns table (issued_code text, valid_until timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- No 0, O, 1 or I: a code is read out over the phone and typed back.
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  fresh text;
  i integer;
  settles uuid;
  until timestamptz := now() + interval '1 hour';
begin
  if not public.is_platform_admin() then
    raise exception 'not a platform admin';
  end if;
  if cycle_in not in ('monthly', 'annual') then
    raise exception 'unknown billing cycle %', cycle_in;
  end if;
  if not exists (select 1 from public.plans where code = plan_code) then
    raise exception 'unknown plan %', plan_code;
  end if;
  if not exists (select 1 from public.agencies where id = target_agency) then
    raise exception 'unknown agency';
  end if;

  -- One open code per agency. Issuing again means the last one was wrong or
  -- lost, and two live codes is how the wrong tier gets activated.
  update public.plan_codes
     set expires_at = now()
   where agency_id = target_agency and used_at is null and expires_at > now();

  loop
    fresh := '';
    for i in 1..8 loop
      fresh := fresh || substr(alphabet, 1 + floor(random() * length(alphabet))::integer, 1);
    end loop;
    exit when not exists (select 1 from public.plan_codes where code = fresh);
  end loop;

  -- Settles the pending request only when it is the same thing. The desk may
  -- well issue a different tier from the one asked for, after a conversation.
  select r.id into settles
  from public.plan_requests r
  where r.agency_id = target_agency and r.status = 'pending'
    and r.plan = plan_code and r.cycle = cycle_in
  order by r.created_at desc
  limit 1;

  insert into public.plan_codes (code, agency_id, plan, cycle, request_id, issued_by, expires_at)
  values (fresh, target_agency, plan_code, cycle_in, settles, auth.uid(), until);

  return query select fresh, until;
end;
$$;

revoke all on function public.admin_issue_plan_code from public;
grant execute on function public.admin_issue_plan_code to authenticated;

-- ---------------------------------------------------------- using one
-- The row is locked before it is checked, so two redemptions of one code in
-- the same second cannot both pass the "not yet used" test.
create or replace function public.redeem_plan_code(code_in text)
returns table (new_plan text, active_until timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  c record;
  base timestamptz;
  span interval;
  until timestamptz;
begin
  select * into c
  from public.plan_codes
  where code = upper(btrim(code_in))
  for update;

  if not found then
    raise exception 'code not found';
  end if;
  if not public.has_role(c.agency_id, array['owner']::public.member_role[]) then
    raise exception 'only the owner of this agency can use this code';
  end if;
  if c.used_at is not null then
    raise exception 'code already used';
  end if;
  if c.expires_at <= now() then
    raise exception 'code expired';
  end if;

  span := case c.cycle when 'annual' then interval '1 year' else interval '1 month' end;

  -- A renewal runs on from the current period rather than from today, so
  -- paying a week early does not cost a week.
  select greatest(coalesce(s.current_period_end, now()), now()) into base
  from public.subscriptions s
  where s.agency_id = c.agency_id;
  until := coalesce(base, now()) + span;

  insert into public.subscriptions (agency_id, plan, status, current_period_end)
  values (c.agency_id, c.plan, 'active', until)
  on conflict (agency_id) do update
    set plan = excluded.plan,
        status = 'active',
        current_period_end = excluded.current_period_end;

  update public.plan_codes
     set used_at = now(), used_by = auth.uid()
   where id = c.id;

  if c.request_id is not null then
    update public.plan_requests set status = 'paid' where id = c.request_id;
  end if;

  return query select c.plan, until;
end;
$$;

revoke all on function public.redeem_plan_code from public;
grant execute on function public.redeem_plan_code to authenticated;

comment on function public.redeem_plan_code is
  'Activates or renews the plan a one-time code was issued for. Owner of that agency only; the code dies on use.';

-- ======================================================================
-- 20260808122300_admin_subscriptions.sql
-- ======================================================================

-- Charta Home · every subscription, for the desk
--
-- The desk's first page is one row per agency. This is one row per
-- subscription, with what it costs where the agency is, when it began, and
-- every activation that has run through it, so a question like "who renewed
-- this month" has a page rather than a query.

create or replace function public.admin_list_subscriptions()
returns table (
  agency_id             uuid,
  agency_name           text,
  agency_country        text,
  agency_city           text,
  agency_currency       char(3),
  owner_name            text,
  owner_email           text,
  current_plan          text,
  plan_status           text,
  started_at            timestamptz,
  trial_until           timestamptz,
  period_until          timestamptz,
  monthly_price         bigint,
  annual_price          bigint,
  activations           integer,
  last_activation_at    timestamptz,
  last_activation_plan  text,
  last_activation_cycle text,
  pending_requests      integer
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_platform_admin() then
    raise exception 'not a platform admin';
  end if;

  return query
  select
    a.id,
    a.name,
    a.country,
    a.city,
    a.currency,
    o.full_name,
    u.email::text,
    s.plan,
    s.status::text,
    s.created_at,
    s.trial_ends_at,
    s.current_period_end,
    pp.monthly,
    pp.annual,
    coalesce(act.n, 0)::integer,
    act.last_at,
    act.last_plan,
    act.last_cycle,
    coalesce((select count(*)::integer from public.plan_requests r
               where r.agency_id = a.id and r.status = 'pending'), 0)
  from public.subscriptions s
  join public.agencies a on a.id = s.agency_id
  left join public.plan_prices pp on pp.plan = s.plan and pp.country = a.country
  left join lateral (
    select m.user_id, m.full_name
    from public.memberships m
    where m.agency_id = a.id and m.role = 'owner'
    order by m.created_at
    limit 1
  ) o on true
  left join auth.users u on u.id = o.user_id
  left join lateral (
    select count(*) as n,
           max(c.used_at) as last_at,
           (array_agg(c.plan order by c.used_at desc))[1] as last_plan,
           (array_agg(c.cycle order by c.used_at desc))[1] as last_cycle
    from public.plan_codes c
    where c.agency_id = a.id and c.used_at is not null
  ) act on true
  order by s.created_at desc;
end;
$$;

revoke all on function public.admin_list_subscriptions from public;
grant execute on function public.admin_list_subscriptions to authenticated;

-- ======================================================================
-- 20260808122400_admin_agency_detail.sql
-- ======================================================================

-- Charta Home · one agency, in full, for the desk
--
-- The listing answers "who is on what". This answers "tell me about this
-- one": its people, its buildings, what it has paid for and asked for, and
-- every code that was ever issued to it. One call, one document, because
-- the page is read far more often than any part of it changes.

create or replace function public.admin_agency_detail(target_agency uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  doc jsonb;
begin
  if not public.is_platform_admin() then
    raise exception 'not a platform admin';
  end if;

  select jsonb_build_object(
    'agency', jsonb_build_object(
      'id', a.id,
      'name', a.name,
      'country', a.country,
      'city', a.city,
      'currency', a.currency,
      'locale', a.locale,
      'whatsapp', a.whatsapp_number,
      'address', a.address,
      'email', a.email,
      'registration', a.registration,
      'joined_at', a.created_at
    ),
    'subscription', (
      select jsonb_build_object(
        'plan', s.plan,
        'status', s.status,
        'started_at', s.created_at,
        'trial_until', s.trial_ends_at,
        'period_until', s.current_period_end,
        'max_apartments', p.max_apartments,
        'monthly_price', pp.monthly,
        'annual_price', pp.annual
      )
      from public.subscriptions s
      left join public.plans p on p.code = s.plan
      left join public.plan_prices pp on pp.plan = s.plan and pp.country = a.country
      where s.agency_id = a.id
    ),
    'members', coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id', m.user_id,
        'name', m.full_name,
        'email', u.email,
        'role', m.role,
        'joined_at', m.created_at
      ) order by m.created_at)
      from public.memberships m
      left join auth.users u on u.id = m.user_id
      where m.agency_id = a.id
    ), '[]'::jsonb),
    'buildings', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', b.id,
        'name', b.name,
        'city', b.city,
        'apartments', (select count(*) from public.apartments ap where ap.building_id = b.id),
        'occupied', (select count(distinct l.apartment_id) from public.leases l
                      join public.apartments ap on ap.id = l.apartment_id
                      where ap.building_id = b.id and l.status = 'active'),
        'created_at', b.created_at
      ) order by b.created_at)
      from public.buildings b
      where b.agency_id = a.id
    ), '[]'::jsonb),
    'money', jsonb_build_object(
      'apartments', (select count(*) from public.apartments ap where ap.agency_id = a.id),
      'tenants', (select count(*) from public.leases l where l.agency_id = a.id and l.status = 'active'),
      'collected_total', coalesce((select sum(py.amount) from public.payments py where py.agency_id = a.id), 0),
      'collected_year', coalesce((select sum(py.amount) from public.payments py
                                   where py.agency_id = a.id and py.paid_on >= date_trunc('year', current_date)), 0),
      'collected_month', coalesce((select sum(py.amount) from public.payments py
                                    where py.agency_id = a.id and py.paid_on >= date_trunc('month', current_date)), 0),
      'payments', (select count(*) from public.payments py where py.agency_id = a.id),
      'last_payment_at', (select max(py.created_at) from public.payments py where py.agency_id = a.id)
    ),
    'requests', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id,
        'plan', r.plan,
        'cycle', r.cycle,
        'currency', r.currency,
        'amount', r.amount,
        'status', r.status,
        'created_at', r.created_at
      ) order by r.created_at desc)
      from public.plan_requests r
      where r.agency_id = a.id
    ), '[]'::jsonb),
    'codes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'code', c.code,
        'plan', c.plan,
        'cycle', c.cycle,
        'issued_at', c.created_at,
        'issued_by', iu.email,
        'expires_at', c.expires_at,
        'used_at', c.used_at,
        'state', case
          when c.used_at is not null then 'used'
          when c.expires_at <= now() then 'expired'
          else 'open' end
      ) order by c.created_at desc)
      from public.plan_codes c
      left join auth.users iu on iu.id = c.issued_by
      where c.agency_id = a.id
    ), '[]'::jsonb)
  )
  into doc
  from public.agencies a
  where a.id = target_agency;

  if doc is null then
    raise exception 'unknown agency';
  end if;

  return doc;
end;
$$;

revoke all on function public.admin_agency_detail from public;
grant execute on function public.admin_agency_detail to authenticated;

-- ======================================================================
-- 20260808122500_tenant_email_reminders.sql
-- ======================================================================

-- Charta Home · a tenant's email, and the reminder that uses it
--
-- The reminder job could reach nobody: WhatsApp needs Meta's approval and
-- SMS has no sender, so every reminder was handed to the agency to forward
-- by hand. An email address is the one channel that works today. The
-- residents table has carried an email column since the start; nothing
-- wrote to it. Now the lease form does, and the views the reminder job and
-- the dashboard read carry it out again.

-- A malformed address would sit silently until the first reminder bounced.
alter table residents
  drop constraint if exists residents_email_shape;
alter table residents drop constraint if exists residents_email_shape;
alter table residents
  add constraint residents_email_shape
  check (email is null or email::text ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$');

-- ----------------------------------------------------------- create_lease
-- The signature changes, which `create or replace` will not do.
drop function if exists public.create_lease(uuid, text, text, bigint, lease_cycle, date, bigint, date);

create or replace function public.create_lease(
  target_apartment uuid,
  resident_name text,
  resident_phone text,
  rent bigint,
  cycle_in lease_cycle default 'monthly',
  starts_on_in date default current_date,
  deposit_in bigint default 0,
  ends_on_in date default null,
  resident_email text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  ap record;
  resident uuid;
  existing_name text;
  existing_email text;
  new_lease uuid;
  clean_name text := btrim(coalesce(resident_name, ''));
  clean_phone text := nullif(btrim(coalesce(resident_phone, '')), '');
  clean_email text := nullif(lower(btrim(coalesce(resident_email, ''))), '');
begin
  select * into ap from public.apartments where id = target_apartment;
  if not found then
    raise exception 'apartment % not found', target_apartment;
  end if;
  if not public.has_role(ap.agency_id, array['owner', 'manager']::public.member_role[]) then
    raise exception 'not allowed to create leases for this agency';
  end if;

  if clean_name = '' then
    raise exception 'a tenant needs a name'
      using errcode = 'check_violation';
  end if;

  if ends_on_in is not null and ends_on_in < starts_on_in then
    raise exception 'lease cannot end before it starts';
  end if;

  if clean_phone is not null then
    select id, full_name, email::text into resident, existing_name, existing_email
    from public.residents
    where agency_id = ap.agency_id and phone_e164 = clean_phone
    limit 1;
  end if;

  if resident is null then
    insert into public.residents (agency_id, full_name, phone_e164, email)
    values (ap.agency_id, clean_name, clean_phone, clean_email)
    returning id into resident;
  else
    -- Same number: believe the person entering it about the name, and
    -- record an address when one is given. A blank address does not erase
    -- one that is already on file.
    update public.residents
       set full_name = clean_name,
           email = coalesce(clean_email, email)
     where id = resident
       and (full_name is distinct from clean_name
            or (clean_email is not null and email is distinct from clean_email));
  end if;

  insert into public.leases (
    agency_id, apartment_id, resident_id, cycle, rent_amount, deposit,
    starts_on, ends_on, status
  )
  values (
    ap.agency_id, ap.id, resident, cycle_in, rent, deposit_in,
    starts_on_in, ends_on_in, 'active'
  )
  returning id into new_lease;

  perform public.ensure_rent_charge(new_lease, starts_on_in);

  return new_lease;
end;
$$;

grant execute on function public.create_lease to authenticated;

-- ---------------------------------------------------- the views carry it
-- Columns are appended, which is the one change `create or replace view`
-- allows, so nothing that reads these by position moves.
create or replace view v_apartment_state
with (security_invoker = true)
as
select
  ap.id            as apartment_id,
  ap.agency_id,
  ap.building_id,
  ap.label,
  ap.rooms,
  ap.bathrooms,
  ap.sqm,
  ap.base_rent,
  l.id             as lease_id,
  l.cycle,
  l.rent_amount,
  r.id             as resident_id,
  r.full_name      as resident_name,
  r.phone_e164     as resident_phone,
  l.starts_on      as lease_started_on,
  (l.id is not null) as is_occupied,
  case
    when l.id is null then null
    else (
      select cs.state
      from v_charge_status cs
      where cs.lease_id = l.id
      order by cs.period_start desc
      limit 1
    )
  end as rent_state,
  l.ends_on        as lease_ends_on,
  r.email::text    as resident_email
from apartments ap
left join leases l
  on l.apartment_id = ap.id and l.status = 'active'
left join residents r
  on r.id = l.resident_id;

create or replace view v_reminder_targets
with (security_invoker = true)
as
select
  rc.id            as rent_charge_id,
  rc.agency_id,
  rc.due_on,
  rc.amount,
  ag.name          as agency_name,
  ag.whatsapp_number as agency_whatsapp,
  ag.currency,
  r.full_name      as resident_name,
  r.phone_e164     as resident_phone,
  ap.label         as apartment_label,
  r.email::text    as resident_email,
  ag.locale        as agency_locale,
  ag.email         as agency_email
from rent_charges rc
join leases l    on l.id = rc.lease_id
join residents r on r.id = l.resident_id
join apartments ap on ap.id = l.apartment_id
join agencies ag on ag.id = rc.agency_id;

-- ======================================================================
-- 20260808122600_three_tiers.sql
-- ======================================================================

-- Charta Home · three tiers, as the sheet says
--
-- The first reading of the pricing sheet produced five tiers, two of them
-- invented to resolve what looked like overlaps. The sheet has three: Starter
-- to thirty apartments, a middle tier to a hundred, Business to two hundred
-- and fifty. The middle one is Professional in Guinea and Growth in Cameroon,
-- one code with two names, which the interface handles.
--
-- Anything that pointed at the two invented tiers is moved first, because
-- the tables reference the catalogue: Pro covered 51 to 100, which is now the
-- middle tier; Enterprise sat above Business, which is now the top.

update subscriptions  set plan = 'growth'   where plan = 'pro';
update subscriptions  set plan = 'business' where plan = 'enterprise';
update plan_requests  set plan = 'growth'   where plan = 'pro';
update plan_requests  set plan = 'business' where plan = 'enterprise';
update plan_codes     set plan = 'growth'   where plan = 'pro';
update plan_codes     set plan = 'business' where plan = 'enterprise';

delete from plan_prices where plan in ('pro', 'enterprise');
delete from plans       where code in ('pro', 'enterprise');

update plans set rank = 2, min_apartments = 31,  max_apartments = 100 where code = 'growth';
update plans set rank = 3, min_apartments = 101, max_apartments = 250 where code = 'business';

comment on table plans is
  'The three tiers. A tier is a band of managed apartments; nothing else is restricted.';

-- ----------------------------------------------- what a flat has been
-- The unit page had a strip of weekdays pinned to one week in August 2026
-- and nothing behind it. What an agency wants to know about a flat is what
-- it has been: how many tenants it has had, what it has brought in over its
-- life, when it was last paid, how long it has stood empty. Appended to the
-- performance view, which is the one change `create or replace` allows.
create or replace view v_apartment_performance
with (security_invoker = true)
as
select
  ap.id                                        as apartment_id,
  ap.agency_id,
  ap.building_id,
  coalesce(collected.total, 0)::bigint         as collected_ytd,
  coalesce(spent.total, 0)::bigint             as expenses_ytd,
  (coalesce(collected.total, 0) - coalesce(spent.total, 0))::bigint as net_ytd,
  case
    when coalesce(collected.total, 0) > 0
      then round(
        ((coalesce(collected.total, 0) - coalesce(spent.total, 0))::numeric
          / collected.total) * 100,
        1
      )
    else null
  end                                          as net_margin_pct,
  coalesce(life.tenants, 0)::integer           as tenants_ever,
  life.first_lease_on                          as first_lease_on,
  life.last_lease_ended_on                     as last_lease_ended_on,
  coalesce(life.collected, 0)::bigint          as collected_lifetime,
  coalesce(life.payments, 0)::integer          as payments_count,
  life.last_payment_on                         as last_payment_on,
  coalesce(spent_life.total, 0)::bigint        as expenses_lifetime,
  coalesce(tk.total, 0)::integer               as tickets_total,
  coalesce(tk.open, 0)::integer                as tickets_open
from apartments ap
left join lateral (
  select sum(p.amount) as total
  from payments p
  join leases l on l.id = p.lease_id
  where l.apartment_id = ap.id
    and p.paid_on >= date_trunc('year', current_date)
) collected on true
left join lateral (
  select sum(e.amount) as total
  from expenses e
  where e.apartment_id = ap.id
    and e.incurred_on >= date_trunc('year', current_date)
) spent on true
left join lateral (
  select
    count(distinct l.resident_id)                                   as tenants,
    min(l.starts_on)                                                as first_lease_on,
    max(l.ends_on) filter (where l.status = 'ended')                as last_lease_ended_on,
    (select sum(p.amount) from payments p where p.lease_id in (select id from leases where apartment_id = ap.id)) as collected,
    (select count(*)     from payments p where p.lease_id in (select id from leases where apartment_id = ap.id)) as payments,
    (select max(p.paid_on) from payments p where p.lease_id in (select id from leases where apartment_id = ap.id)) as last_payment_on
  from leases l
  where l.apartment_id = ap.id
) life on true
left join lateral (
  select sum(e.amount) as total
  from expenses e
  where e.apartment_id = ap.id
) spent_life on true
left join lateral (
  select count(*) as total,
         count(*) filter (where t.status not in ('resolved', 'cancelled')) as open
  from tickets t
  where t.apartment_id = ap.id
) tk on true;

comment on view v_apartment_performance is
  'Per unit money in and money out for the current year, and what the unit has been over its life. Building level expenses are not apportioned.';

-- ======================================================================
-- 20260808122700_payunit.sql
-- ======================================================================

-- Charta Home · paying online, through PayUnit
--
-- Until now a subscription was paid by sending mobile money to a number and
-- the desk issuing a code once the receipt arrived. PayUnit takes the money
-- itself in Cameroon, by MTN MoMo, Orange Money or card, and tells us. So an
-- agency there can pay and be active without anybody at the desk.
--
-- The row is opened before the owner is sent to the gateway and settled
-- after the gateway has been asked, in its own words, what became of it. A
-- notify callback is never enough on its own: it is unsigned, so it is only
-- a reason to ask.

create table if not exists subscription_payments (
  id           uuid primary key default gen_random_uuid(),
  agency_id    uuid not null references agencies (id) on delete cascade,
  request_id   uuid references plan_requests (id) on delete set null,
  plan         text not null references plans (code),
  cycle        text not null check (cycle in ('monthly', 'annual')),
  amount       bigint not null check (amount > 0),
  currency     char(3) not null,
  provider     text not null default 'payunit',
  -- the transaction id we chose and sent to the gateway
  provider_ref text not null unique,
  status       text not null default 'initiated'
               check (status in ('initiated', 'paid', 'failed', 'cancelled')),
  started_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now(),
  settled_at   timestamptz,
  -- the gateway's last answer, kept whole for the day somebody asks
  raw          jsonb
);

create index if not exists subscription_payments_agency_idx on subscription_payments (agency_id, created_at desc);

alter table subscription_payments enable row level security;

-- The agency may read its own. Nothing writes here but the two functions.
drop policy if exists subscription_payments_select on subscription_payments;
drop policy if exists subscription_payments_select on subscription_payments;
create policy subscription_payments_select on subscription_payments for select
  using (agency_id in (select public.current_agency_ids()));

-- ------------------------------------------------------------ opening one
create or replace function public.begin_subscription_payment(
  target_agency uuid,
  plan_code text,
  cycle_in text,
  provider_ref_in text
)
returns table (payment_id uuid, request_id uuid, due bigint, paid_in char(3))
language plpgsql
security definer
set search_path = ''
as $$
declare
  a record;
  price record;
  money bigint;
  req uuid;
begin
  if not public.has_role(target_agency, array['owner']::public.member_role[]) then
    raise exception 'only the owner can pay for a plan';
  end if;
  if cycle_in not in ('monthly', 'annual') then
    raise exception 'unknown billing cycle %', cycle_in;
  end if;
  if not exists (select 1 from public.plans where code = plan_code) then
    raise exception 'unknown plan %', plan_code;
  end if;
  if provider_ref_in !~ '^[A-Za-z0-9]{6,64}$' then
    raise exception 'transaction id must be letters and digits';
  end if;

  select ag.country, ag.currency into a from public.agencies ag where ag.id = target_agency;

  -- Online payment needs a price. A country without a list is a quote, and a
  -- quote is a conversation, not a checkout page.
  select pp.currency, pp.monthly, pp.annual into price
  from public.plan_prices pp
  where pp.plan = plan_code and pp.country = a.country;
  if not found then
    raise exception 'no list price for % in %', plan_code, a.country;
  end if;

  money := case cycle_in when 'annual' then price.annual else price.monthly end;

  -- The same request row the manual path records, so the desk sees one
  -- kind of thing whether the money came by gateway or by receipt.
  insert into public.plan_requests (agency_id, plan, cycle, currency, amount, requested_by)
  values (target_agency, plan_code, cycle_in, price.currency, money, auth.uid())
  returning id into req;

  return query
    insert into public.subscription_payments
      (agency_id, request_id, plan, cycle, amount, currency, provider_ref, started_by)
    values
      (target_agency, req, plan_code, cycle_in, money, price.currency, provider_ref_in, auth.uid())
    returning subscription_payments.id, subscription_payments.request_id,
              subscription_payments.amount, subscription_payments.currency;
end;
$$;

revoke all on function public.begin_subscription_payment from public;
grant execute on function public.begin_subscription_payment to authenticated;

-- ----------------------------------------------------------- settling one
-- Service role only. The server calls this after asking the gateway, never
-- from anything the browser sent. Idempotent: a payment settled twice, which
-- a callback and a return page can easily do, extends the period once.
create or replace function public.settle_subscription_payment(
  payment_id_in uuid,
  final_status text,
  raw_in jsonb default null
)
returns table (outcome text, new_plan text, active_until timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  p record;
  base timestamptz;
  span interval;
  until timestamptz;
begin
  if final_status not in ('paid', 'failed', 'cancelled') then
    raise exception 'unknown final status %', final_status;
  end if;

  select * into p from public.subscription_payments where id = payment_id_in for update;
  if not found then
    raise exception 'unknown payment';
  end if;

  -- Already settled. Say what happened and change nothing.
  if p.status <> 'initiated' then
    select s.current_period_end into until from public.subscriptions s where s.agency_id = p.agency_id;
    return query select p.status::text, p.plan, until;
    return;
  end if;

  update public.subscription_payments
     set status = final_status, settled_at = now(), raw = coalesce(raw_in, raw)
   where id = p.id;

  if final_status <> 'paid' then
    return query select final_status, p.plan, null::timestamptz;
    return;
  end if;

  span := case p.cycle when 'annual' then interval '1 year' else interval '1 month' end;

  -- A renewal runs on from the current period rather than from today, so
  -- paying a week early does not cost a week. Same rule as a code.
  select greatest(coalesce(s.current_period_end, now()), now()) into base
  from public.subscriptions s where s.agency_id = p.agency_id;
  until := coalesce(base, now()) + span;

  insert into public.subscriptions (agency_id, plan, status, current_period_end)
  values (p.agency_id, p.plan, 'active', until)
  on conflict (agency_id) do update
    set plan = excluded.plan,
        status = 'active',
        current_period_end = excluded.current_period_end;

  if p.request_id is not null then
    update public.plan_requests set status = 'paid' where id = p.request_id;
  end if;

  return query select 'paid'::text, p.plan, until;
end;
$$;

revoke all on function public.settle_subscription_payment from public;
revoke all on function public.settle_subscription_payment from authenticated;

-- --------------------------------------------------- the desk sees them
create or replace function public.admin_agency_detail(target_agency uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  doc jsonb;
begin
  if not public.is_platform_admin() then
    raise exception 'not a platform admin';
  end if;

  select jsonb_build_object(
    'agency', jsonb_build_object(
      'id', a.id, 'name', a.name, 'country', a.country, 'city', a.city, 'currency', a.currency,
      'locale', a.locale, 'whatsapp', a.whatsapp_number, 'address', a.address, 'email', a.email,
      'registration', a.registration, 'joined_at', a.created_at
    ),
    'subscription', (
      select jsonb_build_object(
        'plan', s.plan, 'status', s.status, 'started_at', s.created_at,
        'trial_until', s.trial_ends_at, 'period_until', s.current_period_end,
        'max_apartments', p.max_apartments, 'monthly_price', pp.monthly, 'annual_price', pp.annual
      )
      from public.subscriptions s
      left join public.plans p on p.code = s.plan
      left join public.plan_prices pp on pp.plan = s.plan and pp.country = a.country
      where s.agency_id = a.id
    ),
    'members', coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id', m.user_id, 'name', m.full_name, 'email', u.email, 'role', m.role, 'joined_at', m.created_at
      ) order by m.created_at)
      from public.memberships m left join auth.users u on u.id = m.user_id
      where m.agency_id = a.id
    ), '[]'::jsonb),
    'buildings', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', b.id, 'name', b.name, 'city', b.city,
        'apartments', (select count(*) from public.apartments ap where ap.building_id = b.id),
        'occupied', (select count(distinct l.apartment_id) from public.leases l
                      join public.apartments ap on ap.id = l.apartment_id
                      where ap.building_id = b.id and l.status = 'active'),
        'created_at', b.created_at
      ) order by b.created_at)
      from public.buildings b where b.agency_id = a.id
    ), '[]'::jsonb),
    'money', jsonb_build_object(
      'apartments', (select count(*) from public.apartments ap where ap.agency_id = a.id),
      'tenants', (select count(*) from public.leases l where l.agency_id = a.id and l.status = 'active'),
      'collected_total', coalesce((select sum(py.amount) from public.payments py where py.agency_id = a.id), 0),
      'collected_year', coalesce((select sum(py.amount) from public.payments py
                                   where py.agency_id = a.id and py.paid_on >= date_trunc('year', current_date)), 0),
      'collected_month', coalesce((select sum(py.amount) from public.payments py
                                    where py.agency_id = a.id and py.paid_on >= date_trunc('month', current_date)), 0),
      'payments', (select count(*) from public.payments py where py.agency_id = a.id),
      'last_payment_at', (select max(py.created_at) from public.payments py where py.agency_id = a.id)
    ),
    'requests', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'plan', r.plan, 'cycle', r.cycle, 'currency', r.currency, 'amount', r.amount,
        'status', r.status, 'created_at', r.created_at
      ) order by r.created_at desc)
      from public.plan_requests r where r.agency_id = a.id
    ), '[]'::jsonb),
    'codes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'code', c.code, 'plan', c.plan, 'cycle', c.cycle, 'issued_at', c.created_at, 'issued_by', iu.email,
        'expires_at', c.expires_at, 'used_at', c.used_at,
        'state', case when c.used_at is not null then 'used' when c.expires_at <= now() then 'expired' else 'open' end
      ) order by c.created_at desc)
      from public.plan_codes c left join auth.users iu on iu.id = c.issued_by
      where c.agency_id = a.id
    ), '[]'::jsonb),
    -- Money that came through the gateway, which never needed a code.
    'online_payments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', sp.id, 'plan', sp.plan, 'cycle', sp.cycle, 'amount', sp.amount, 'currency', sp.currency,
        'provider', sp.provider, 'provider_ref', sp.provider_ref, 'status', sp.status,
        'created_at', sp.created_at, 'settled_at', sp.settled_at
      ) order by sp.created_at desc)
      from public.subscription_payments sp where sp.agency_id = a.id
    ), '[]'::jsonb)
  )
  into doc
  from public.agencies a
  where a.id = target_agency;

  if doc is null then
    raise exception 'unknown agency';
  end if;
  return doc;
end;
$$;

revoke all on function public.admin_agency_detail from public;
grant execute on function public.admin_agency_detail to authenticated;

